insert into public.modules (id, slug, title, summary, initially_unlocked, codex, bg_theme, sprite_url) values (1, 'edafologia', 'Edafología y Física de Suelos', 'Textura, estructura, agua del suelo, compactación, erosión y lectura de perfiles.', true, '[{"heading":"1.1 · Textura: la huella mineral","body":["La textura es la proporción de arena, limo y arcilla en la tierra fina (partículas menores a 2 mm). Según el USDA, la arena mide entre 2 y 0,05 mm, el limo entre 0,05 y 0,002 mm y la arcilla menos de 0,002 mm.","Con esos porcentajes se ubica el suelo en el triángulo textural, que define 12 clases (arenosa, franca, franco-arcillosa, arcillosa, etc.). La textura condiciona la retención de agua, la aireación, la CIC y la facilidad de laboreo.","A escala agronómica la textura no cambia con el manejo: es una propiedad heredada del material parental y de la meteorización. Por eso se maneja en torno a ella, no contra ella."]},{"heading":"1.1 · Cómo se mide: el método de Bouyoucos","body":["Se dispersa la muestra con hexametafosfato de sodio y agitación, para separar los agregados en partículas individuales, y se lleva a una probeta con agua.","Las partículas sedimentan según la Ley de Stokes: las más grandes caen más rápido. A los 40 segundos la arena ya decantó, así que el hidrómetro mide limo + arcilla en suspensión; a las 2 horas solo queda arcilla en suspensión.","El método de la pipeta es la referencia de laboratorio. En terreno, el \"tacto\" (formar una cinta con la muestra húmeda) permite una estimación rápida."]},{"heading":"1.1 · Estructura: la arquitectura del suelo","body":["La estructura es la forma en que las partículas se agrupan en agregados (peds). Los cementan arcillas, materia orgánica, óxidos de Fe y Al, el calcio (floculante) y la biología: raíces, hifas y la glomalina de los hongos micorrícicos.","Tipos principales: granular (típica de horizontes A con buena MO), bloques angulares y subangulares, prismática, columnar (asociada a suelos sódicos) y laminar (frecuente por compactación). Sin estructura: grano simple (arenas) o masiva.","El grado (débil, moderado, fuerte) indica qué tan definidos y estables son los agregados."]},{"heading":"1.1 · Estabilidad y manejo","body":["El sodio intercambiable (PSI alto) dispersa las arcillas: el suelo se sella, forma costras y estructura columnar. El calcio, por ejemplo aplicado como yeso, flocula y ayuda a recuperarlo.","La labranza excesiva y el tránsito con suelo húmedo destruyen agregados; la materia orgánica, las raíces vivas y los cultivos de cobertura los estabilizan.","La estabilidad de agregados se evalúa con tamizado en húmedo: más agregados estables significa mejor infiltración y menos erosión."]},{"heading":"1.2 · El agua retenida y el potencial mátrico","body":["El suelo retiene agua por adhesión a las superficies de las partículas y por capilaridad en los poros. Mientras más seco está, con más fuerza la retiene: esa fuerza se expresa como potencial mátrico (negativo), en kPa o bar.","Los poros grandes se vacían primero y a tensiones bajas; los poros finos (típicos de suelos arcillosos) retienen agua a tensiones muy altas."]},{"heading":"1.2 · Los puntos de referencia","body":["Saturación: todos los poros llenos de agua. Capacidad de Campo (CC): humedad tras drenar el exceso por gravedad, asociada a unos −33 kPa (−1/3 bar); en suelos arenosos se usa a menudo −10 kPa.","Punto de Marchitez Permanente (PMP): humedad a unos −1.500 kPa (−15 bar), donde la mayoría de los cultivos ya no recupera la turgencia.","Agua disponible (AD) = CC − PMP. Los suelos arcillosos tienen la CC y el PMP más altos; los francos y franco-limosos suelen tener la mayor agua disponible; los arenosos, la menor."]},{"heading":"1.2 · La curva característica de humedad","body":["La curva relaciona el contenido volumétrico de agua (θ) con el potencial mátrico. Se obtiene en laboratorio con ollas y placas de presión de Richards: muestras saturadas se someten a presiones conocidas (por ejemplo 0,33 y 15 bar) hasta equilibrar y se mide el agua retenida.","La curva presenta histéresis: a un mismo potencial, el suelo que se está secando retiene más agua que el que se está humedeciendo."]},{"heading":"1.2 · De la curva al riego","body":["Lámina de agua disponible: AD (mm) = (θCC − θPMP) × profundidad de raíces (mm). Ejemplo: θCC 30 %, θPMP 15 % y raíces a 600 mm dan 0,15 × 600 = 90 mm.","No se espera a llegar al PMP: se riega al alcanzar el agotamiento permisible, típicamente 30 a 50 % del AD según el cultivo. Con 50 % en el ejemplo, se reponen 45 mm.","Los tensiómetros miden en terreno entre 0 y unos −80 kPa: el rango útil para programar el riego de la mayoría de los frutales y hortalizas."]},{"heading":"1.3 · Densidad y porosidad","body":["La densidad aparente (Da) incluye los poros; la densidad real (Dr) considera solo los sólidos y en suelos minerales ronda 2,65 g/cm³. La porosidad total se estima como 1 − Da/Dr.","Valores típicos de Da: suelos arenosos 1,5–1,6 g/cm³; francos 1,3–1,4; arcillosos 1,1–1,3. Los Andisoles (trumaos) pueden bajar de 0,9 g/cm³.","Los macroporos drenan y airean; los microporos retienen agua. Un buen suelo agrícola combina ambos."]},{"heading":"1.3 · Aireación: las raíces también respiran","body":["Las raíces y la biota consumen O₂ y liberan CO₂; el intercambio ocurre por difusión a través de los poros con aire.","Se considera que bajo un 10 % de porosidad de aire (a capacidad de campo) aparece hipoxia: menor absorción de agua y nutrientes, más enfermedades de raíz y pérdidas de N por desnitrificación."]},{"heading":"1.3 · Compactación","body":["La compactación aumenta la Da, elimina macroporos y eleva la resistencia mecánica. Sus causas principales son el tránsito de maquinaria y el pisoteo, sobre todo con el suelo húmedo, cerca de capacidad de campo, cuando es más deformable.","El pie de arado es una capa compactada que se forma justo bajo la profundidad de labranza cuando se labra siempre a la misma profundidad.","Umbrales orientativos que restringen raíces: Da cercana a 1,6 g/cm³ en suelos francos, 1,45–1,5 en arcillosos y 1,75–1,8 en arenosos. Con penetrómetro de cono, sobre 2 MPa el crecimiento radicular se reduce fuertemente."]},{"heading":"1.3 · Recuperación","body":["Subsolar solo con el suelo friable o seco, para fracturar la capa en vez de amasarla; luego proteger el resultado con tránsito controlado (siempre por las mismas huellas).","Los cultivos de cobertura con raíz pivotante (como el rábano forrajero) funcionan como \"subsolado biológico\", y la materia orgánica mejora la resiliencia del suelo."]},{"heading":"1.4 · El proceso: desprender, transportar, depositar","body":["La erosión hídrica comienza con el impacto de la gota de lluvia, que desprende partículas (salpicadura) y sella la superficie. Luego el escurrimiento las transporta y las deposita aguas abajo.","Formas: laminar (pérdida pareja y poco visible), en surcos o regueros (canales pequeños que la labranza borra) y cárcavas (canales profundos que la labranza normal no puede cruzar ni borrar).","La erosión eólica mueve partículas por reptación, saltación y suspensión; es mayor en suelos secos, sueltos y sin cobertura."]},{"heading":"1.4 · Estimar la pérdida: la USLE","body":["La Ecuación Universal de Pérdida de Suelo estima la pérdida media anual: A = R · K · LS · C · P.","R es la erosividad de la lluvia; K, la erodabilidad del suelo (mayor en suelos limosos o de arenas muy finas con poca materia orgánica); LS, el largo y la inclinación de la pendiente; C, la cobertura y el manejo; P, las prácticas de conservación.","R, K y LS dependen del lugar; el agricultor actúa sobre C y P."]},{"heading":"1.4 · La erosión en Chile","body":["Según estudios de CIREN, cerca de la mitad del territorio nacional presenta algún grado de erosión, con situaciones críticas en el secano costero e interior de la zona central.","La combinación de lluvias concentradas en invierno, laderas sin cobertura y suelos degradados acelera la pérdida de la capa arable, que tarda siglos en formarse."]},{"heading":"1.4 · Prácticas de conservación","body":["Cobertura: cultivos de cobertura, mulch, rastrojos y cero labranza (bajan el factor C).","Prácticas mecánicas: cultivo en contorno, fajas, terrazas, zanjas de infiltración y control de cárcavas con diques (bajan el factor P).","Contra el viento: cortinas cortaviento y mantener el suelo cubierto."]},{"heading":"1.5 · La calicata","body":["Una calicata es un hoyo de observación de aproximadamente 1 × 1,5 m y 1,2 a 1,5 m de profundidad (o hasta la roca). Se describe la cara mejor iluminada, desde la superficie hacia abajo.","Se registran: límites y espesor de cada horizonte, color Munsell (matiz, valor y croma), textura al tacto, estructura, consistencia, raíces, poros, moteados, gravas y reacción al HCl (presencia de carbonatos)."]},{"heading":"1.5 · Horizontes maestros","body":["O: orgánico, de restos vegetales. A: mineral con materia orgánica acumulada, más oscuro. E: de eluviación, lavado de arcilla, hierro o MO, más claro. B: de acumulación o alteración (Bt arcilla iluvial, Bw cambio de color o estructura, Bk carbonatos, Bn sodio). C: material parental poco alterado. R: roca.","Los sufijos agregan detalle: p (alterado por arado, como en Ap), g (gleyzación por saturación de agua), t (arcilla iluvial), k (carbonatos), n (sodio)."]},{"heading":"1.5 · Factores formadores","body":["Jenny resumió la formación del suelo como función de cinco factores: clima, organismos, relieve, material parental y tiempo.","Los moteados grises y anaranjados indican saturación de agua y condiciones reductoras alternadas con oxidación: drenaje imperfecto. Son clave para decidir drenaje y especies."]},{"heading":"1.5 · Suelos de Chile","body":["Andisoles (trumaos) del centro-sur, formados de cenizas volcánicas: arcillas amorfas alofana e imogolita, baja Da, alta retención de agua, alta MO y fuerte fijación de fósforo.","Ñadis: andisoles hidromórficos con una capa cementada de fierrillo que impide el drenaje. Suelos rojos arcillosos (Alfisoles y Ultisoles) en el secano y la precordillera; Mollisoles en el valle central; Aridisoles y Entisoles en el norte."]}]'::jsonb, 'bg-clay-pit', null)
insert into public.modules (id, slug, title, summary, initially_unlocked, codex, bg_theme, sprite_url) values (2, 'fertilidad', 'Fertilidad y Nutrición Vegetal', 'CIC, pH, macro y micronutrientes, diagnóstico foliar y programas de fertilización.', false, '[{"heading":"2.1 · Los coloides: superficie con carga","body":["Las arcillas y el humus son coloides: partículas diminutas, de enorme superficie específica y con carga eléctrica, casi siempre negativa. Sobre esa carga se adsorben cationes como Ca²⁺, Mg²⁺, K⁺, Na⁺, NH₄⁺, H⁺ y Al³⁺.","La carga puede ser permanente, por sustitución isomórfica dentro de la red de la arcilla (montmorillonita, vermiculita), o variable, dependiente del pH, como en el humus, los óxidos y las arcillas alofánicas de los Trumaos."]},{"heading":"2.1 · La CIC y la saturación de bases","body":["La CIC es la cantidad total de cationes que el suelo puede retener e intercambiar, expresada en cmol(+)/kg. Un suelo arenoso pobre en materia orgánica puede tener menos de 5; uno arcilloso o rico en humus, más de 25. El humus aporta entre 150 y 300 cmol(+)/kg, la caolinita apenas 3 a 15.","La saturación de bases es el porcentaje de la CIC ocupado por Ca, Mg, K y Na. Una saturación alta indica un suelo poco ácido y bien provisto; una baja indica que H⁺ y Al³⁺ dominan el complejo de intercambio.","En un suelo agrícola equilibrado el Ca suele ocupar 60-80 % de la CIC, el Mg 10-20 % y el K 2-6 %."]},{"heading":"2.1 · Por qué importa en el manejo","body":["Una CIC baja significa poca \"memoria\" de nutrientes: conviene fertilizar en dosis fraccionadas, porque el exceso se pierde por lixiviación. Una CIC alta amortigua cambios de pH y retiene mejor el potasio y el amonio.","Los aniones como el nitrato (NO₃⁻) no se retienen en la CIC y se mueven con el agua; el fosfato, en cambio, se fija químicamente a óxidos de Fe y Al o al calcio.","Aumentar la materia orgánica es la forma más efectiva de subir la CIC de un suelo en el mediano plazo."]},{"heading":"2.2 · El pH y la disponibilidad de nutrientes","body":["El pH es el logaritmo negativo de la actividad de H⁺: un suelo a pH 5 tiene diez veces más acidez activa que uno a pH 6. La mayoría de los cultivos rinde mejor entre pH 6,0 y 7,0, donde la disponibilidad conjunta de nutrientes es mayor.","A pH ácido aumentan la solubilidad del Al, Mn y Fe (con riesgo de toxicidad) y baja la de P, Ca, Mg y Mo. A pH alcalino caen el Fe, Mn, Zn, Cu y B, y el P precipita como fosfatos de calcio."]},{"heading":"2.2 · Acidez y aluminio en los suelos del sur","body":["Las lluvias abundantes lixivian las bases y acidifican el suelo, proceso que acentúan los fertilizantes amoniacales. Bajo pH 5,5 aparece Al³⁺ intercambiable, que daña el ápice de la raíz y frena su crecimiento.","El indicador clave es la saturación de aluminio: Al intercambiable dividido por la suma de bases más Al. Sobre 5-10 % ya afecta a especies sensibles como alfalfa y cebada; el trigo y la avena son algo más tolerantes.","En Chile, los Andisoles (Trumaos) y Ultisoles (rojo arcillosos) de La Araucanía y Los Lagos son los que más requieren corrección de acidez."]},{"heading":"2.2 · Encalado","body":["La cal (carbonato de calcio) neutraliza la acidez: el carbonato consume H⁺ y el calcio desplaza al aluminio del complejo de intercambio. La dolomita aporta además magnesio.","La eficacia depende del poder de neutralización (equivalente CaCO₃) y de la finura: las partículas finas reaccionan antes. La cal se mueve poco en el perfil, por lo que debe incorporarse o aplicarse con anticipación al cultivo.","El yeso (sulfato de calcio) no corrige el pH, pero aporta calcio en profundidad y reduce la toxicidad de aluminio en el subsuelo."]},{"heading":"2.3 · Nitrógeno: el más dinámico","body":["La planta absorbe N como nitrato (NO₃⁻) y amonio (NH₄⁺). En el suelo, la materia orgánica se mineraliza a amonio y las bacterias nitrificantes lo oxidan a nitrato, que es móvil.","Las pérdidas principales son la lixiviación de nitratos, la volatilización de amoníaco (urea aplicada en superficie sobre suelo húmedo y caluroso o alcalino) y la desnitrificación en suelos saturados, que libera N₂ y N₂O.","El N es móvil dentro de la planta: su deficiencia produce clorosis primero en las hojas viejas."]},{"heading":"2.3 · Fósforo: el más inmóvil","body":["El fósforo se absorbe como ortofosfato (H₂PO₄⁻ y HPO₄²⁻). Se mueve muy poco en el suelo: llega a la raíz por difusión, a milímetros de distancia, por lo que la localización del fertilizante y las micorrizas son decisivas.","En suelos ácidos se fija a óxidos de Fe y Al; en los Andisoles la alofana retiene fosfato con mucha fuerza, de modo que exigen dosis altas. En suelos calcáreos precipita como fosfato de calcio.","Su deficiencia retrasa el crecimiento y puede dar tonos púrpura en hojas por acumulación de antocianinas."]},{"heading":"2.3 · Potasio: el regulador","body":["El K⁺ regula la apertura de estomas, la presión de turgencia, la activación de enzimas y el transporte de azúcares hacia frutos. Se asocia al calibre, color, firmeza y azúcar de la fruta.","Su deficiencia se ve como necrosis en el borde de las hojas viejas (quemado marginal), porque es móvil en la planta.","El cloruro de potasio (muriato) es la fuente más barata, pero el sulfato de potasio es preferible en cultivos sensibles al cloro, como frambuesa, palto o tabaco."]},{"heading":"2.4 · Calcio, magnesio y azufre","body":["El calcio forma las paredes celulares (pectatos) y se mueve solo por el xilema con la transpiración: no se redistribuye. Por eso su falta aparece en órganos que transpiran poco, como frutos y ápices: bitter pit en manzana, pudrición apical en tomate, tip burn en lechuga.","El magnesio es el átomo central de la clorofila. Es móvil, así que su deficiencia da clorosis intervenal en hojas viejas. El exceso de K o de amonio compite con su absorción.","El azufre forma aminoácidos (cisteína, metionina). Se absorbe como sulfato y es poco móvil en la planta: su falta amarillea las hojas nuevas, y es frecuente en suelos del sur pobres en materia orgánica."]},{"heading":"2.4 · Micronutrientes","body":["Se requieren en gramos por hectárea, pero su ausencia limita el rendimiento igual que un macro (Ley del Mínimo). Los principales son Fe, Mn, Zn, Cu, B, Mo, Cl y Ni.","El hierro es inmóvil: su falta da clorosis intervenal en hojas nuevas, típica en suelos calcáreos o alcalinos (clorosis férrica). Se corrige con quelatos estables a pH alto, como Fe-EDDHA.","El boro participa en la germinación del polen y en la cuaja; tiene un rango muy estrecho entre deficiencia y toxicidad, y la toxicidad por B en aguas de riego es un problema en zonas del norte de Chile. El zinc es clave en la síntesis de auxinas: su falta produce hojas pequeñas y entrenudos cortos (roseta)."]},{"heading":"2.4 · Móviles e inmóviles: la clave del diagnóstico","body":["Si el nutriente es móvil en la planta (N, P, K, Mg), la deficiencia aparece en las hojas viejas, porque la planta lo traslada a los brotes. Si es inmóvil (Ca, S, Fe, Mn, Zn, Cu, B), aparece en hojas nuevas o en frutos.","Este patrón permite una primera hipótesis en terreno, que luego se confirma con análisis foliar."]},{"heading":"2.5 · Análisis de suelo y foliar","body":["El análisis de suelo indica lo que el suelo puede ofrecer: pH, materia orgánica, N mineral, P Olsen, K, bases intercambiables, CE y micronutrientes. Su valor depende de un buen muestreo: muchas submuestras por sector homogéneo y a la profundidad de raíces.","El análisis foliar indica lo que la planta efectivamente absorbió. Se compara con rangos de suficiencia y exige respetar el tipo de hoja y la época estandarizados para cada especie: en frutales, normalmente hojas maduras del brote del año en verano."]},{"heading":"2.5 · Cuánto fertilizar: el balance","body":["La dosis sale de un balance: demanda del cultivo (extracción por tonelada esperada) menos el aporte del suelo, dividido por la eficiencia del fertilizante. Ningún fertilizante se aprovecha al 100 %: la eficiencia del N suele estar entre 40 y 70 %.","Las \"4 R\" resumen la buena práctica: la fuente correcta, en la dosis correcta, en el momento correcto y en el lugar correcto."]},{"heading":"2.5 · Salinidad y fertirriego","body":["La conductividad eléctrica (CE, en dS/m) mide sales solubles. Cada especie tiene un umbral de CE en el extracto de saturación sobre el cual pierde rendimiento: el frijol y la frutilla son sensibles; la cebada y la remolacha, tolerantes.","Los fertilizantes son sales: el índice salino indica cuánto suben la CE. En suelos o aguas salinas conviene preferir fuentes de bajo índice y regar con una fracción de lavado que arrastre las sales bajo la zona de raíces.","En suelos sódicos el problema no es la CE sino el sodio intercambiable (PSI): se corrige con calcio (yeso) y lavado."]}]'::jsonb, 'bg-salt-flats', null)
insert into public.modules (id, slug, title, summary, initially_unlocked, codex, bg_theme, sprite_url) values (3, 'agrometeorologia', 'Agrometeorología y Clima', 'Balance de radiación, heladas, horas frío, grados día y evapotranspiración.', false, '[{"heading":"3.1 · Onda corta y onda larga","body":["El sol emite radiación de onda corta (0,3 a 3 µm). Cerca de la mitad es radiación fotosintéticamente activa (PAR, 400-700 nm), la que usan las plantas.","La Tierra, las plantas y las nubes, mucho más frías, emiten radiación de onda larga (infrarrojo térmico). En noches despejadas el suelo pierde onda larga hacia el cielo sin que nada la devuelva: así se enfría y se forman las heladas radiativas."]},{"heading":"3.1 · Albedo y radiación neta","body":["El albedo es la fracción de la radiación de onda corta que una superficie refleja: la nieve fresca refleja 80-90 %, un cultivo verde cerca de 20-25 % y un suelo oscuro y húmedo apenas 10 %.","La radiación neta es lo que queda: onda corta absorbida más onda larga recibida menos onda larga emitida. De día es positiva; de noche, negativa."]},{"heading":"3.1 · Dónde se va la energía","body":["La radiación neta se reparte entre calor latente (evaporar agua), calor sensible (calentar el aire) y flujo de calor al suelo. Un cultivo bien regado usa la mayor parte en evapotranspirar; un suelo seco calienta el aire.","Por eso un huerto regado está más fresco que un potrero seco, y un suelo húmedo y compacto guarda más calor del día para liberarlo en la noche.","Las mallas sombra y las cubiertas modifican este balance: reducen la onda corta que llega al cultivo y la onda larga que este pierde de noche."]},{"heading":"3.2 · Grados día","body":["El desarrollo de plantas e insectos se acelera con la temperatura sobre un umbral base. Los grados día (GD) suman cada día la temperatura media menos esa base: con base 10 °C, un día de media 18 °C aporta 8 GD.","Cada fase (emergencia, floración, cosecha) necesita una suma térmica más o menos constante. Por eso los GD predicen fechas de cosecha en maíz o vid, y el momento de control de plagas como la polilla de la manzana (Cydia pomonella)."]},{"heading":"3.2 · Horas frío y receso","body":["Los frutales caducos entran en endodormancia en otoño y necesitan acumular frío para brotar parejo en primavera. Una hora frío clásica es una hora bajo 7,2 °C.","El modelo Utah (unidades de frío) da peso máximo a temperaturas cercanas a 6-7 °C y resta frío con temperaturas altas. El modelo dinámico (porciones de frío) es hoy el más usado para climas templados como el chileno.","Si el frío no alcanza, la brotación y la floración son tardías y desuniformes. En esos casos se usan compensadores de frío, como la cianamida hidrogenada."]},{"heading":"3.2 · Temperaturas extremas","body":["Sobre unos 35 °C muchas especies cierran estomas, baja la fotosíntesis y aparecen daños como golpe de sol en frutos. El calor en floración puede reducir la viabilidad del polen y la cuaja.","La temperatura del aire se mide en una garita meteorológica a 1,5-2 m, ventilada y a la sombra; un termómetro al sol puede marcar varios grados más que el aire real."]},{"heading":"3.3 · Tipos de helada","body":["La helada radiativa ocurre en noches despejadas y calmas: el suelo pierde onda larga, el aire en contacto se enfría y se forma una inversión térmica, con aire más cálido unos metros arriba. Es la más común en los valles centrales de Chile.","La helada advectiva llega con una masa de aire polar y viento: no hay inversión y el frío afecta toda la columna de aire. Es mucho más difícil de controlar.","La helada blanca deposita escarcha porque el aire alcanza el punto de rocío; la helada negra ocurre con aire seco, sin escarcha visible, y suele ser más dañina porque no libera calor latente."]},{"heading":"3.3 · Daño y temperatura crítica","body":["El daño ocurre cuando se forma hielo dentro de los tejidos. Cada estado fenológico tiene una temperatura crítica: las flores abiertas y los frutos recién cuajados son más sensibles que las yemas dormidas.","Las tablas de temperaturas críticas suelen indicar el valor que mata al 10 % y al 90 % de los órganos en cada estado."]},{"heading":"3.3 · Métodos de control","body":["Pasivos: elegir sitios con buen drenaje de aire frío (evitar hondonadas), mantener el suelo húmedo, compacto y sin cubierta vegetal alta para que acumule calor, y elegir variedades de floración tardía.","Activos: los ventiladores (máquinas de viento) mezclan el aire cálido de la inversión con el frío de abajo, y solo sirven en heladas radiativas. La aspersión sobre el follaje libera calor latente al congelarse el agua: debe mantenerse sin interrupción hasta que el hielo se derrita. Los calefactores agregan calor directo.","Si la aspersión se interrumpe o la tasa de agua es baja, la evaporación roba calor y el daño puede ser peor que sin proteger."]},{"heading":"3.4 · Humedad del aire","body":["La humedad relativa (HR) es el vapor presente respecto del máximo que el aire admite a esa temperatura. Como el máximo sube con la temperatura, la HR baja al mediodía y sube de noche aunque el vapor no cambie.","El déficit de presión de vapor (DPV) es la diferencia entre la presión de vapor de saturación y la real: mide cuánto \"tira\" la atmósfera del agua de la hoja. Un DPV alto aumenta la transpiración y puede cerrar estomas.","El punto de rocío es la temperatura a la que el aire se satura al enfriarse: sirve para anticipar heladas y el mojado de las hojas, que favorece enfermedades."]},{"heading":"3.4 · ET de referencia","body":["La evapotranspiración de referencia (ET₀) es lo que evapotranspira una pradera de referencia bien regada. La FAO la estandarizó con la ecuación de Penman-Monteith (FAO-56), que usa radiación, temperatura, humedad y viento.","Un método simple es la bandeja de evaporación clase A: la evaporación medida se multiplica por un coeficiente de bandeja (Kp, alrededor de 0,7-0,8) para estimar ET₀."]},{"heading":"3.4 · Del clima al riego","body":["La evapotranspiración del cultivo es ETc = ET₀ × Kc. El coeficiente de cultivo (Kc) cambia con la fenología: es bajo en la etapa inicial, máximo en pleno desarrollo y baja hacia la madurez.","El viento aumenta la ET porque renueva el aire húmedo junto a la hoja; también daña físicamente brotes y frutos, por eso se usan cortavientos.","Las estaciones meteorológicas de la red agroclimática (Agromet en Chile) publican ET₀ diaria para programar el riego."]},{"heading":"3.5 · Los climas de Chile","body":["El norte es desértico por el Anticiclón del Pacífico Sur y la corriente de Humboldt, que estabilizan la atmósfera; en la costa aparece la camanchaca. El centro tiene clima mediterráneo: lluvias concentradas en invierno y veranos secos, por eso la agricultura depende del riego.","Hacia el sur aumentan las lluvias y disminuye la temperatura; la Patagonia es fría y ventosa. La Cordillera de los Andes guarda el agua como nieve, que alimenta los ríos en primavera y verano."]},{"heading":"3.5 · El Niño y La Niña","body":["El ENOS (El Niño-Oscilación del Sur) alterna fases cálidas y frías del Pacífico ecuatorial. En la zona central de Chile, El Niño suele traer inviernos más lluviosos y La Niña, inviernos más secos.","Los años secos y fríos también favorecen heladas más frecuentes. Seguir los pronósticos estacionales ayuda a decidir siembras, seguros y uso del agua."]},{"heading":"3.5 · Sequía y cambio climático","body":["Desde 2010 la zona central vivió una megasequía con déficit de lluvias por más de una década, con menor nieve acumulada y caudales reducidos.","Las tendencias apuntan a menos precipitación y más temperatura en el centro y norte, con la isoterma 0 °C más alta y menos reserva de nieve. Esto desplaza zonas aptas para cultivos hacia el sur.","La adaptación combina riego tecnificado, especies y portainjertos tolerantes, cosecha de agua, seguros agrícolas y monitoreo agroclimático."]}]'::jsonb, 'bg-black-frost', null)
insert into public.modules (id, slug, title, summary, initially_unlocked, codex, bg_theme, sprite_url) values (4, 'fisiologia', 'Fisiología Vegetal y Relaciones Hídricas', 'Fotosíntesis, transpiración, potencial hídrico, hormonas y fenología.', false, '[{"heading":"4.1 · Fase luminosa y ciclo de Calvin","body":["En los tilacoides del cloroplasto la luz rompe el agua, libera O₂ y genera ATP y NADPH. En el estroma, el ciclo de Calvin usa esa energía para fijar CO₂ en azúcares.","La enzima que fija el CO₂ es la Rubisco, la proteína más abundante del planeta. Su problema: también reacciona con O₂, y esa reacción, la fotorrespiración, desperdicia carbono y energía, sobre todo con calor y estomas cerrados."]},{"heading":"4.1 · Plantas C3, C4 y CAM","body":["Las C3 (trigo, arroz, papa, la mayoría de los frutales) fijan el CO₂ directamente con la Rubisco; su primer producto tiene 3 carbonos. Sufren más fotorrespiración en climas cálidos.","Las C4 (maíz, caña de azúcar, sorgo y muchas malezas como el pasto bermuda) fijan primero el CO₂ con la PEP carboxilasa en el mesófilo y lo concentran en la vaina del haz (anatomía Kranz). Así casi eliminan la fotorrespiración y usan mejor el agua y el nitrógeno en calor.","Las CAM (cactus, piña, agave) abren estomas de noche, guardan el CO₂ como ácido málico y lo usan de día con los estomas cerrados: máxima eficiencia en el uso del agua."]},{"heading":"4.1 · Factores limitantes","body":["La fotosíntesis responde a la luz hasta un punto de saturación; bajo el punto de compensación, la respiración consume más de lo que la hoja fija. Las hojas sombreadas del interior de un árbol pueden quedar bajo ese punto.","El CO₂, la temperatura, el agua (vía estomas) y el nitrógeno (gran parte del N de la hoja está en la Rubisco) también limitan la tasa fotosintética."]},{"heading":"4.2 · Potencial hídrico","body":["El potencial hídrico (Ψ) mide la energía libre del agua y se expresa en megapascales (MPa). El agua pura libre tiene Ψ = 0; en suelo y plantas los valores son negativos, y el agua siempre fluye de potencial mayor (menos negativo) a menor (más negativo).","Sus componentes son el potencial osmótico (solutos, siempre negativo), el de presión (turgencia, positivo en células vivas; tensión, negativo en el xilema) y el mátrico (adhesión a superficies, relevante en suelos y paredes)."]},{"heading":"4.2 · El continuo suelo-planta-atmósfera","body":["El agua entra por la raíz, atraviesa la endodermis (la banda de Caspary obliga a pasar por membranas), sube por el xilema y sale por los estomas. La transpiración genera la tensión que tira de la columna de agua: es la teoría de la cohesión-tensión.","El gradiente va de un suelo húmedo (−0,03 MPa) a una atmósfera seca que puede estar bajo −50 MPa. La mayor resistencia está en la raíz y en el paso de líquido a vapor en la hoja."]},{"heading":"4.2 · Medir el estrés hídrico","body":["La cámara de presión (de Scholander) mide el potencial xilemático: se encierra una hoja cortada y se aplica presión hasta que el agua aflora en el corte. Esa presión iguala la tensión que tenía el xilema.","El potencial de tallo a mediodía, con la hoja embolsada para detener la transpiración, es el indicador más usado para riego en frutales y vides. El potencial antes del amanecer refleja el agua del suelo que explora la raíz.","Otras herramientas son los dendrómetros (contracción diaria del tronco) y la termografía infrarroja (hojas estresadas se calientan)."]},{"heading":"4.3 · El dilema del estoma","body":["Para fijar CO₂ la hoja debe abrir los estomas, pero por el mismo poro sale vapor de agua. Una planta C3 transpira cientos de litros de agua por cada kilo de materia seca que produce.","La transpiración no es solo pérdida: enfría la hoja, mueve los nutrientes disueltos por el xilema (incluido el calcio) y mantiene la tensión que sube el agua."]},{"heading":"4.3 · Cómo se abren y cierran","body":["Dos células oclusivas rodean el poro. Cuando acumulan K⁺ y solutos, entra agua, se hinchan y el poro se abre. La luz azul, el CO₂ interno bajo y la humedad favorecen la apertura.","El ácido abscísico (ABA), producido cuando el suelo se seca, provoca la salida de K⁺ y el cierre del estoma. El DPV alto, el calor extremo y el CO₂ interno alto también los cierran."]},{"heading":"4.3 · Uso eficiente del agua","body":["La eficiencia en el uso del agua (EUA) es el carbono fijado por unidad de agua transpirada. Es mayor en plantas CAM, luego C4 y menor en C3.","El riego deficitario controlado (RDC) aprovecha que un estrés moderado en fases poco sensibles reduce el crecimiento vegetativo sin afectar mucho la producción, ahorrando agua y mejorando la calidad, por ejemplo en vides para vino.","El secado parcial de raíces (PRD) alterna el riego entre ambos lados del árbol: las raíces del lado seco envían ABA y la planta cierra parcialmente estomas mientras sigue hidratada."]},{"heading":"4.4 · Las promotoras","body":["Las auxinas (ácido indolacético) se producen en ápices y semillas. Causan la dominancia apical, el enraizamiento de estacas y el crecimiento del fruto; sintéticas como el ANA se usan para enraizar y para ralear.","Las giberelinas alargan tallos, rompen la latencia de algunas semillas y agrandan bayas: en uva de mesa se aplica ácido giberélico (GA₃) para alargar el racimo y aumentar el calibre.","Las citoquininas, formadas en la raíz, estimulan la división celular, retrasan la senescencia y rompen la dominancia apical. El balance auxina/citoquinina decide si un tejido forma raíces o brotes."]},{"heading":"4.4 · Etileno y ABA","body":["El etileno es un gas que desencadena la maduración de frutos climatéricos (manzana, palta, plátano, tomate) y la abscisión de hojas y frutos. En postcosecha se controla con frío, ventilación, atmósfera controlada y el 1-MCP, que bloquea sus receptores.","El ácido abscísico (ABA) induce la dormancia de yemas y semillas y cierra estomas ante sequía."]},{"heading":"4.4 · Uso agronómico","body":["Los reguladores se usan a dosis muy bajas y el efecto depende de la especie, la variedad, la dosis y el estado fenológico. Un mismo producto puede ralear o cuajar según el momento.","Ejemplos: ethephon (libera etileno) para uniformar maduración o ralear, AVG para retrasar la caída de frutos y la maduración, prohexadiona-calcio para frenar el crecimiento de brotes."]},{"heading":"4.5 · Fuentes y sumideros","body":["Una fuente es un órgano que exporta azúcares: la hoja adulta que fotosintetiza o un órgano de reserva que se vacía en primavera. Un sumidero es un órgano que los consume o los guarda: frutos, brotes en crecimiento, raíces y hojas jóvenes.","La relación hoja/fruto resume el equilibrio: en manzano se necesitan cerca de 30 a 40 hojas bien iluminadas por fruto para lograr calibre y azúcar. Con menos hojas por fruto, la fruta queda chica y sin sabor."]},{"heading":"4.5 · El transporte por el floema","body":["Los azúcares viajan por el floema, sobre todo como sacarosa (en rosáceas como manzano y cerezo también como sorbitol). El modelo de flujo por presión de Münch explica el movimiento: la carga de azúcar en la fuente atrae agua y sube la presión, y la descarga en el sumidero la baja.","A diferencia del xilema, que solo sube, el floema mueve los azúcares en cualquier dirección: hacia la raíz, hacia un fruto o hacia un brote apical."]},{"heading":"4.5 · La fuerza del sumidero y el añerismo","body":["Los frutos con semillas en crecimiento son sumideros muy fuertes: le ganan los azúcares a las raíces, a los brotes y a las yemas que deben formar flores para el año siguiente.","Por eso una carga excesiva genera añerismo (alternancia productiva): un año mucha fruta pequeña y al siguiente casi nada. El raleo temprano de flores o frutos reparte mejor los asimilados y estabiliza la producción.","El anillado del tronco o de ramas corta el floema por un tiempo: los azúcares quedan en la copa, lo que aumenta el calibre o la cuaja, pero también priva a la raíz."]}]'::jsonb, 'bg-ancient-roots', null)
insert into public.modules (id, slug, title, summary, initially_unlocked, codex, bg_theme, sprite_url) values (5, 'botanica', 'Botánica Agrícola y Silvestre', 'Morfología, taxonomía, flora nativa y reconocimiento de malezas.', false, '[{"heading":"5.1 · Raíces","body":["Las dicotiledóneas suelen tener raíz pivotante: un eje principal que profundiza (alfalfa, zanahoria). Las monocotiledóneas tienen raíces fasciculadas, un haz de raíces finas de igual grosor (trigo, maíz, pastos).","Hay raíces adventicias, que nacen de tallos u hojas (estacas, raíces de anclaje del maíz), y raíces reservantes engrosadas (betarraga, camote)."]},{"heading":"5.1 · Tallos y sus modificaciones","body":["El tallo tiene nudos, donde nacen hojas y yemas, y entrenudos. Muchas especies lo modifican: el rizoma es un tallo subterráneo horizontal (correhuela, chépica); el tubérculo es un tallo subterráneo engrosado con yemas u \"ojos\" (papa); el bulbo es un tallo corto rodeado de hojas carnosas (cebolla, ajo).","El estolón es un tallo rastrero que enraíza en los nudos (frutilla). Los zarcillos de la vid y las espinas de la zarzamora o del espino también son estructuras modificadas.","La papa es un tallo y no una raíz: sus \"ojos\" son yemas en nudos, y por eso brota de ellos."]},{"heading":"5.1 · La hoja","body":["Partes: lámina, pecíolo y, en algunas, estípulas. Las monocotiledóneas suelen tener nervaduras paralelas y vaina que abraza el tallo; las dicotiledóneas, nervaduras reticuladas.","Una hoja es simple si tiene una sola lámina y compuesta si se divide en folíolos (el nogal, la rosa). La filotaxis describe cómo se ordenan en el tallo: alterna, opuesta o verticilada.","En las gramíneas, la lígula y las aurículas en la unión de la vaina con la lámina permiten identificar especies incluso sin flor."]},{"heading":"5.2 · La flor","body":["Una flor completa tiene cáliz (sépalos), corola (pétalos), androceo (estambres, con anteras que producen polen) y gineceo (pistilo: estigma, estilo y ovario). Al conjunto de cáliz y corola se le llama perianto.","El ovario es súpero si se ubica sobre la inserción de las otras piezas (cerezo, tomate) e ínfero si queda bajo ellas, fusionado al receptáculo (manzano, peral, zapallo).","Por su simetría, la flor es actinomorfa o radial si tiene varios planos de simetría (rosa, manzano) y zigomorfa si tiene uno solo (arveja, orquídea)."]},{"heading":"5.2 · Inflorescencias","body":["Las flores se agrupan en inflorescencias. En el racimo cada flor tiene su pedicelo a lo largo de un eje (uva, raps); en la espiga las flores son sésiles (trigo); en la umbela todos los pedicelos salen de un mismo punto (zanahoria, cebolla); en el corimbo las flores quedan a la misma altura (peral).","El capítulo de las asteráceas (girasol, lechuga) parece una flor, pero es un conjunto de muchas flores pequeñas sobre un receptáculo común."]},{"heading":"5.2 · Sexualidad de la planta","body":["Las flores pueden ser hermafroditas (con estambres y pistilo) o unisexuales. Una especie es monoica si tiene flores masculinas y femeninas en la misma planta (maíz, nogal, zapallo) y dioica si están en plantas distintas (kiwi, espárrago, pistacho).","En especies dioicas hay que plantar machos polinizantes junto a las hembras productivas: en kiwi se usa cerca de un macho cada seis a ocho hembras."]},{"heading":"5.3 · El nombre científico","body":["Linneo propuso el sistema binomial: género con mayúscula y epíteto específico con minúscula, ambos en cursiva (Solanum tuberosum). A veces se agrega el autor abreviado (L. por Linneo).","Los nombres comunes cambian entre regiones (palta y aguacate, poroto y frijol); el científico es único y universal, por eso se usa en etiquetas de plaguicidas, registros y viveros."]},{"heading":"5.3 · La jerarquía","body":["Reino, división, clase, orden, familia, género y especie. Los nombres de familia terminan en -aceae: Rosaceae, Fabaceae, Poaceae.","Bajo la especie están la subespecie, la variedad botánica y, en agricultura, el cultivar (variedad cultivada), que se escribe entre comillas simples: Malus domestica ''Gala''."]},{"heading":"5.3 · Familias de importancia agrícola","body":["Rosaceae: manzano, peral, cerezo, frutilla, frambuesa. Fabaceae (leguminosas): poroto, arveja, alfalfa; fijan nitrógeno con Rhizobium. Poaceae (gramíneas): trigo, maíz, arroz, praderas.","Solanaceae: papa, tomate, ají, berenjena. Brassicaceae (crucíferas): repollo, brócoli, raps, rábano. Cucurbitaceae: zapallo, melón, sandía. Asteraceae: lechuga, maravilla, alcachofa.","Conocer la familia orienta la rotación: cultivos de la misma familia comparten plagas y enfermedades."]},{"heading":"5.4 · Del óvulo al fruto","body":["La polinización lleva el polen al estigma; la fecundación ocurre cuando el tubo polínico llega al óvulo. En las angiospermas es doble: un núcleo forma el embrión y otro el endosperma.","El fruto es el ovario desarrollado y la semilla, el óvulo fecundado. La pared del ovario se transforma en el pericarpio (epicarpio, mesocarpio y endocarpio). Si el fruto se desarrolla sin fecundación es partenocárpico (plátano, algunas mandarinas)."]},{"heading":"5.4 · Tipos de fruto","body":["Carnosos: la drupa tiene un carozo leñoso (durazno, cereza, aceituna); la baya es carnosa con semillas en la pulpa (uva, tomate, arándano); el pomo es un falso fruto donde la parte comestible es el receptáculo (manzana, pera); el hesperidio es la baya de los cítricos.","Secos: los dehiscentes se abren al madurar, como la legumbre, que lo hace por dos suturas (poroto, arveja). Los indehiscentes no se abren: la cariopsis es el grano de los cereales, con la semilla soldada al pericarpio; el aquenio es pequeño y con una semilla libre (girasol); la nuez tiene pared dura.","Frutos agregados vienen de varios pistilos de una flor (frambuesa, frutilla) y los múltiples, de varias flores (piña, mora de árbol)."]},{"heading":"5.4 · La semilla","body":["La semilla tiene tegumento (testa), embrión (radícula, plúmula y cotiledones) y reservas. Las monocotiledóneas tienen un cotiledón y guardan reservas en el endosperma (maíz, trigo); muchas dicotiledóneas las guardan en los cotiledones (poroto, arveja).","La germinación necesita agua, oxígeno y temperatura adecuada. Algunas semillas tienen dormancia: por cubierta dura e impermeable (se rompe con escarificación) o por inhibidores internos (se rompe con estratificación en frío húmedo, como en muchas rosáceas)."]},{"heading":"5.5 · Qué hace exitosa a una maleza","body":["Una maleza compite con el cultivo por luz, agua y nutrientes, y puede hospedar plagas. Las más agresivas producen miles de semillas, con dormancia que les permite esperar años en el banco de semillas del suelo.","Por su ciclo se clasifican en anuales (completan su vida en una temporada), bianuales y perennes. Las perennes con rizomas, estolones o bulbillos son las más difíciles, porque rebrotan aunque se corte la parte aérea."]},{"heading":"5.5 · Hoja ancha y hoja angosta","body":["Las malezas de hoja angosta son principalmente gramíneas (pasto bermuda o chépica, hualcacho, ballica) y ciperáceas (chufa o coquito, Cyperus rotundus, con tubérculos). Las de hoja ancha son dicotiledóneas: yuyo, rábano silvestre, quingüilla, correhuela, malvilla.","La distinción importa porque muchos herbicidas son selectivos: los graminicidas controlan gramíneas sin dañar cultivos de hoja ancha, y las auxinas sintéticas (2,4-D, MCPA) controlan hojas anchas en cereales.","Las ciperáceas se distinguen de las gramíneas por su tallo triangular y macizo (\"las ciperáceas tienen aristas\")."]},{"heading":"5.5 · Control integrado","body":["Identificar la maleza en estado de plántula permite controlarla cuando es más sensible. El momento crítico de competencia es el periodo en que el cultivo debe estar limpio para no perder rendimiento.","El manejo integrado combina rotación de cultivos, cultivos de cobertura, control mecánico, herbicidas de distintos modos de acción y evitar que las malezas semillen. Usar siempre el mismo herbicida selecciona biotipos resistentes, como la ballica resistente a glifosato.","La cuscuta es una planta parásita sin clorofila que se enrolla en el hospedero; la correhuela (Convolvulus arvensis) es una perenne de rizomas profundos que rebrota desde varios metros de profundidad."]}]'::jsonb, 'bg-geometric-grove', null)
insert into public.modules (id, slug, title, summary, initially_unlocked, codex, bg_theme, sprite_url) values (6, 'fruticultura', 'Fruticultura General', 'Portainjertos, sistemas de conducción, poda, polinización y cuaja.', false, '[{"heading":"6.1 · Por qué injertar","body":["La variedad (copa) se propaga sobre un portainjerto para conservar sus características: de semilla saldría una planta distinta, porque la mayoría de los frutales son heterocigotos.","El portainjerto controla el vigor y el tamaño del árbol, la precocidad, la tolerancia a suelos (asfixia, caliza, salinidad) y la resistencia a plagas y enfermedades del suelo como nematodos y Phytophthora."]},{"heading":"6.1 · Portainjertos clásicos","body":["Manzano: la serie Malling, como el M9 (enanizante, exige soporte y suelos buenos) y el MM106 o MM111 (más vigorosos). Cerezo: Gisela 6 y Gisela 12 (enanizantes y precoces), Colt, Maxma 14 o el franco Mazzard. Vid: portainjertos americanos resistentes a filoxera, como 1103 Paulsen o Freedom.","En Chile, gran parte de las vides se cultiva sobre pie franco porque el país está libre de filoxera; aun así se usan portainjertos contra nematodos, salinidad o falta de vigor."]},{"heading":"6.1 · El injerto y su compatibilidad","body":["Para que prenda, el cambium de ambas partes debe quedar en contacto. Las técnicas más comunes son el injerto de yema (ojo vivo o dormido, chip budding) y los de púa (hendidura, inglés).","La incompatibilidad aparece cuando las especies están poco emparentadas: la unión es débil, con engrosamiento o necrosis, el árbol amarillea y puede quebrarse. Se evita con un interinjerto compatible, como en el peral sobre membrillero.","El injerto también transmite virus: por eso se usa material certificado."]},{"heading":"6.2 · La luz es la cosecha","body":["Un huerto produce según la luz que intercepta. Los sistemas de conducción buscan cubrir rápido el espacio, iluminar todo el árbol y facilitar la cosecha y la aplicación de productos.","La sombra interior baja la inducción floral, el color y el calibre de la fruta. Bajo un 30 % de luz plena las yemas pierden fertilidad."]},{"heading":"6.2 · Sistemas","body":["Vaso abierto: tres a cinco ramas desde un tronco corto, con el centro despejado; tradicional en carozos. Eje central: un líder vertical con ramas laterales cortas que decrecen hacia arriba; base de los huertos de manzano en alta densidad.","Sistemas en pared o de ejes múltiples (KGB, UFO, Tall Spindle, ejes en V) forman muros frutales estrechos, fáciles de cosechar y aptos para la mecanización.","La vid se conduce en espaldera (vino) o parronal español (uva de mesa), donde el follaje forma un techo que protege los racimos."]},{"heading":"6.2 · Densidad y vigor","body":["Las altas densidades (más de 2.000 árboles/ha en manzano) necesitan portainjertos enanizantes, soporte, riego tecnificado y mano de obra calificada, pero producen antes y con mejor calidad.","La orientación norte-sur de las hileras reparte mejor la luz entre ambas caras en Chile. La distancia entre hileras debe ser mayor que la altura del árbol para evitar el sombreamiento mutuo."]},{"heading":"6.3 · Principios de la poda","body":["La poda invernal estimula el vigor: al quitar yemas, la reserva de la raíz se reparte entre menos puntos de crecimiento. La poda de verano, en cambio, frena el vigor y mejora la luz sobre la fruta.","Despunte (rebaje) estimula brotes cerca del corte; raleo (eliminar una rama completa desde su base) abre la copa sin provocar rebrote excesivo."]},{"heading":"6.3 · Dónde fructifica cada especie","body":["Antes de podar hay que saber dónde está la fruta: el manzano y el peral fructifican sobre dardos y lamburdas de madera de dos años o más; el durazno, en ramillas mixtas del año anterior; el cerezo, en dardos (ramilletes de mayo) y en la base de las ramillas de un año; la vid, en brotes nacidos de cargadores o pitones de madera de un año.","Una poda que elimina esa madera elimina la cosecha."]},{"heading":"6.3 · Equilibrio y chupones","body":["Los chupones son brotes vigorosos y verticales que consumen carbohidratos, sombrean y rara vez fructifican. Aparecen tras podas fuertes, exceso de N o ramas arqueadas.","Un árbol equilibrado tiene crecimiento moderado de brotes y fruta suficiente. Exceso de vigor: poca fruta y mucha sombra. Poco vigor: fruta chica y envejecimiento de la madera.","Herramientas para frenar el vigor: poda de verano, inclinar ramas, anillado, portainjertos enanizantes, riego deficitario y reguladores como la prohexadiona-calcio."]},{"heading":"6.4 · Autoincompatibilidad y polinizantes","body":["Muchas variedades de manzano, peral y cerezo son autoincompatibles: su polen no fecunda sus propias flores. Necesitan una variedad polinizante compatible, que florezca al mismo tiempo, intercalada en el huerto.","En cerezo la compatibilidad depende de los alelos S: variedades con el mismo grupo S no se polinizan entre sí. Existen variedades autofértiles, como Lapins o Santina, que simplifican el diseño."]},{"heading":"6.4 · Abejas y cuaja","body":["Las abejas melíferas son el principal polinizador; se recomiendan del orden de 6 a 10 colmenas fuertes por hectárea en cerezo o manzano, ubicadas al inicio de la floración. Los abejorros (Bombus) trabajan con menos temperatura.","La cuaja es el paso de flor a fruto en crecimiento. El clima frío y lluvioso en floración, las heladas y la falta de reservas reducen la cuaja; el periodo efectivo de polinización depende de la vida útil del óvulo."]},{"heading":"6.4 · Raleo","body":["Un árbol con demasiada fruta produce fruta chica, de menor azúcar y color, y puede no florecer el año siguiente (añerismo). El raleo ajusta la carga a la capacidad del árbol.","Puede ser de flores o de frutos, manual o químico (ANA, BA o metamitrón en manzano). Mientras más temprano, mayor es el efecto sobre el calibre final, porque la división celular del fruto ocurre en las primeras semanas."]},{"heading":"6.5 · Las fases de la dormancia","body":["En otoño, los días cortos y el frío detienen el crecimiento, las hojas caen y las yemas entran en receso. Se distinguen tres fases: paradormancia (otro órgano inhibe la yema, como la dominancia apical), endodormancia (la inhibición está dentro de la yema y solo la rompe el frío) y ecodormancia (la yema ya está lista, pero espera temperaturas favorables).","Durante el invierno, las yemas acumulan frío hasta cumplir su requerimiento; recién entonces pueden brotar cuando suben las temperaturas."]},{"heading":"6.5 · Medir el frío","body":["El método más simple cuenta horas bajo 7,2 °C. El modelo Utah asigna unidades de frío según la temperatura: el rango de 2,5 a 9 °C suma más, y las horas sobre unos 16 °C restan. El modelo dinámico (porciones de frío) funciona mejor en climas de invierno templado como Chile central.","Los requerimientos varían mucho: hay manzanos y cerezos de alto requerimiento (sobre 1.000 horas frío), y durazneros y almendros de bajo requerimiento (300 a 600 horas). La variedad debe calzar con el frío del lugar."]},{"heading":"6.5 · Cuando falta frío","body":["Un invierno insuficiente produce brotación tardía, escasa y dispareja, floración prolongada que no coincide con los polinizantes y menor cuaja.","Para compensar se usan compensadores de frío como la cianamida hidrogenada, aplicada unas semanas antes de la brotación esperada; requiere un manejo estricto de la dosis y del momento porque es tóxica.","El aceite mineral invernal y la defoliación oportuna también ayudan a uniformar la brotación."]}]'::jsonb, 'bg-overgrown-canopy', null)
insert into public.modules (id, slug, title, summary, initially_unlocked, codex, bg_theme, sprite_url) values (7, 'cranberry', 'Cranberry', 'Acidófila de raíz superficial, heladas por aspersión y cosecha en agua.', true, '[{"heading":"7.1 · Una planta de turbera","body":["El cranberry (Vaccinium macrocarpon) es una Ericácea perenne y siempreverde, nativa de las turberas de Norteamérica. Se cultiva en \"camas\" planas y niveladas, sobre arena o suelos orgánicos, que pueden inundarse y drenarse.","Forma tallos rastreros (runners), que cubren la cama, y tallos verticales (uprights), que son los productivos: fructifican en la yema apical formada la temporada anterior. Una cama productiva tiene del orden de 400 a 600 uprights por pie cuadrado."]},{"heading":"7.1 · Raíces superficiales","body":["Sus raíces son finas, sin pelos radicales, y se concentran en los primeros 10 a 15 cm. Dependen de micorrizas ericoides para absorber nutrientes.","Esa raíz tan superficial la hace sensible a la sequía, a la salinidad y a la asfixia: el mal drenaje favorece a Phytophthora cinnamomi."]},{"heading":"7.1 · pH y nitrógeno","body":["Es una especie acidófila: su pH óptimo está entre 4,0 y 5,5. Sobre pH 6,5 bloquea la absorción de hierro y aparece clorosis intervenal en los brotes nuevos.","Absorbe mal el nitrato: exige nitrógeno amoniacal (sulfato de amonio, por ejemplo), que además ayuda a mantener el suelo ácido. Las dosis de N son bajas, porque el exceso vuelve la planta vegetativa."]},{"heading":"7.2 · Riego","body":["Con raíces en los primeros 15 cm, el cranberry tolera poco el déficit hídrico pero tampoco el exceso. En camas de arena se riega con tensiómetros, manteniendo la tensión entre 20 y 30 centibares.","El riego por aspersión cumple tres funciones: hidratar, proteger contra heladas y enfriar la fruta en días de calor."]},{"heading":"7.2 · Heladas","body":["En invierno profundo, ya endurecida, la planta tolera hasta cerca de −18 °C. En primavera, con brotes y flores, la tolerancia cae a pocos grados bajo cero.","El control activo es la aspersión continua: al congelarse, el agua libera calor latente y mantiene los tejidos cerca de 0 °C. Debe seguir hasta que el hielo se derrita. Si el hielo se ve opaco y seco en vez de transparente y goteando, la tasa de agua es insuficiente y la planta se está congelando."]},{"heading":"7.2 · Calor y color","body":["Con alta radiación y temperatura aparece el golpe de sol (sunscald): daño fisiológico en la cara expuesta de la baya. Riegos cortos de enfriamiento lo reducen.","El color rojo depende de las antocianinas, cuya síntesis se gatilla con noches frías al final de la temporada."]},{"heading":"7.3 · Runners y uprights","body":["El cranberry (Vaccinium macrocarpon) es una enredadera perenne de hoja persistente. Forma tallos rastreros, los runners, que cubren la cama, y de ellos nacen tallos verticales cortos, los uprights, que son los que producen la fruta.","La productividad de una cama depende de su densidad de uprights con flor: una cama sana tiene varios cientos por metro cuadrado."]},{"heading":"7.3 · La yema terminal y el ciclo anual","body":["La yema terminal del upright es mixta: contiene el brote y las flores de la temporada siguiente. Se forma a fines del verano anterior, por lo que una temporada con estrés, mucha carga o exceso de nitrógeno reduce la flor del año próximo.","En invierno la planta está en reposo y, ya endurecida, tolera fuertes heladas. En primavera la yema se hincha, se abre y el brote se alarga; los botones florales cuelgan de pedicelos curvos en el estado de \"gancho\" (hook), justo antes de abrir.","Al avanzar desde la yema cerrada hasta el gancho, la tolerancia a la helada cae de varios grados bajo cero a cerca de 0 °C: el estado fenológico decide cuándo hay que proteger."]},{"heading":"7.3 · La floración","body":["Cada upright lleva varias flores en su base. La flor cuelga, tiene cuatro pétalos rosados vueltos hacia atrás y un cono de estambres que recuerda la cabeza y el pico de una grulla: de ahí el nombre \"craneberry\".","La floración dura varias semanas al inicio del verano y es la etapa más sensible del cultivo. Solo una parte de las flores llega a fruto: una cuaja de 30 a 40 % se considera buena.","Desde la cuaja, la baya tarda unos dos a tres meses en crecer y tomar color antes de la cosecha."]},{"heading":"7.4 · Enfermedades","body":["Phytophthora cinnamomi pudre las raíces en sectores mal drenados: aparecen manchones de plantas rojizas y débiles. La prevención es el drenaje y la nivelación de las camas.","El Fairy Ring, asociado al hongo Psilocybe, forma anillos que se expanden cada año, con plantas muertas en el borde activo."]},{"heading":"7.4 · Insectos","body":["El cranberry fruitworm pone huevos en las bayas recién cuajadas y la larva consume su interior: se monitorea post-cuaja. La mosquita de la yema (Dasineura oxycoccana) mata las yemas apicales de uprights tiernos y reduce la floración siguiente.","El manejo integrado combina monitoreo con trampas y redes, umbrales de daño y productos compatibles con las abejas, indispensables para la polinización."]},{"heading":"7.4 · Malezas","body":["La cuscuta es una planta parásita sin clorofila: sus tallos amarillo-anaranjados se enrollan en el cranberry y le extraen savia mediante haustorios. Se dispersa por semillas y fragmentos, y es la maleza más problemática.","Pastos, juncos y helechos compiten en camas mal establecidas; mantener la cama densa es la mejor defensa."]},{"heading":"7.5 · Polinización","body":["La flor del cranberry produce poco néctar y su polen se libera en tétradas desde anteras tubulares, por lo que la polinización necesita insectos. Se introducen colmenas de abejas melíferas o colonias de abejorros durante la floración.","Una buena polinización aumenta el número de semillas por baya, y con ellas el tamaño del fruto."]},{"heading":"7.5 · Cosecha en agua y en seco","body":["Para la industria (jugos, fruta deshidratada) se cosecha en agua: se inunda la cama, batidoras desprenden las bayas y estas flotan gracias a sus cámaras de aire internas; luego se arrean con barreras flotantes.","Para mercado fresco se cosecha en seco, con peinadoras mecánicas. La fruta cosechada en agua dura poco, porque los patógenos entran por la cicatriz del pedicelo y por el daño de la batidora."]},{"heading":"7.5 · Calidad","body":["El precio de la fruta para industria depende mucho del color, que se mide como antocianinas totales (TAcy). Cosechar después de algunas noches frías mejora el valor.","El hongo Cottonball (Monilinia oxycocci) infecta flores y la baya se llena de una masa algodonosa blanca. Las pudriciones de campo se manejan con fungicidas en floración y buena ventilación de la cama."]}]'::jsonb, 'bg-red-swamp', null)
insert into public.modules (id, slug, title, summary, initially_unlocked, codex, bg_theme, sprite_url) values (8, 'frambuesa', 'Frambuesa', 'Primocane vs floricane, camellones, conducción en V y pre-frío.', true, '[{"heading":"8.1 · Raíz perenne, cañas bianuales","body":["La frambuesa (Rubus idaeus) es una Rosácea con raíz y corona perennes, pero sus cañas viven dos temporadas. El primer año la caña se llama primocane (crece vegetativa); el segundo, floricane (fructifica y luego muere).","Brota desde yemas de la corona y desde raíces gemíferas que emiten hijuelos a distancia: por eso la plantación \"camina\" y puede volverse invasiva entre hileras.","Su raíz es muy sensible a la asfixia y a Phytophthora: se planta en camellones elevados, en suelos francos y bien drenados, con riego por goteo. También es sensible al cloro, por lo que el potasio se aplica como sulfato o nitrato y no como cloruro (muriato)."]},{"heading":"8.1 · Remontantes y no remontantes","body":["Las variedades no remontantes (floricane, como Meeker) fructifican en verano sobre la caña de segundo año, después de acumular entre 600 y 1.000 horas frío en receso.","Las remontantes (primocane, como Heritage, la más plantada en Chile) fructifican en otoño en la punta de la caña del mismo año, por lo que pueden manejarse con una sola cosecha anual cortando todas las cañas en invierno, o con doble cosecha."]},{"heading":"8.1 · Flor y fruto","body":["La flor es muy atractiva para las abejas, que aumentan la cuaja: cada drupéolo es un pistilo fecundado, de modo que una mala polinización deja frutos deformes.","El fruto es un agregado de drupéolos. A diferencia de la mora, al cosecharlo el receptáculo queda en la planta y la frambuesa sale hueca."]},{"heading":"8.2 · Por qué necesita soporte","body":["Las cañas de frambuesa son largas y flexibles: con el peso de la fruta, el viento y la lluvia se doblan y caen al pasillo. Una espaldera las mantiene erguidas, expone la fruta a la luz, ventila la hilera y permite cosechar rápido y sin daño.","La estructura se instala antes o durante el primer año, porque después de plantado cuesta trabajar entre las plantas sin dañarlas."]},{"heading":"8.2 · Sistemas de espaldera","body":["La espaldera simple (vertical) usa uno o dos pares de alambres a cada lado de las cañas, a unos 0,8 y 1,5 m de altura. La espaldera en T o en V usa crucetas de 0,6 a 1 m de ancho que separan las cañas hacia los lados y abren el centro de la hilera.","En túneles y cultivos remontantes es común sujetar las cañas con mallas o alambres móviles que se suben a medida que las primocanes crecen."]},{"heading":"8.2 · Postes, anclajes y tensores","body":["Los postes intermedios van cada 6 a 10 m; los postes de cabecera son más gruesos y se inclinan hacia afuera, y se anclan al suelo con un \"muerto\" (ancla enterrada) para resistir la tensión de todos los alambres.","Se usa alambre galvanizado de alta resistencia. Los tensores permiten recuperar la tensión que se pierde con el peso y los cambios de temperatura: un alambre suelto deja caer las cañas y las roza con el viento.","Revisar y tensar la estructura antes de cada temporada, y reemplazar postes podridos o quebrados, evita que una cabecera ceda y arrastre toda la hilera."]},{"heading":"8.3 · Conducción en V","body":["Las cañas se conducen con alambres. El sistema en \"V\" o cruceta (T-trellis) separa las cañas hacia ambos lados: abre el centro de la hilera, mejora la luz y la aireación y reduce Botrytis.","Una hilera densa y cerrada guarda humedad, favorece enfermedades y complica la cosecha."]},{"heading":"8.3 · Raleo y eliminación de cañas","body":["En variedades no remontantes, las primocanes compiten con las floricanes que están produciendo: se ralean temprano, dejando las más vigorosas. Un raleo tardío deja cañas débiles para el año siguiente.","Tras la cosecha, las floricanes se cortan a ras y se sacan del huerto: ya no producirán y pueden hospedar enfermedades."]},{"heading":"8.3 · Exposición de la fruta","body":["Con radiación UV directa y altas temperaturas aparece el White Drupelet Disorder: drupéolos blancos que bajan la calidad. Una canopia que proteja la fruta y mallas sombra en zonas cálidas lo reducen."]},{"heading":"8.4 · Enfermedades","body":["Botrytis cinerea causa pudrición gris en flores y frutos, sobre todo con lluvia en floración y cosecha. El Spur blight (tizón de la yema, Didymella applanata) deja manchas púrpura oscuras en los nudos de la caña.","Agrobacterium tumefaciens forma agallas leñosas en el cuello y las raíces; entra por heridas y se evita con plantas sanas y certificadas.","Virus como el RBDV causan desgrane (crumbly berry); otros, como los mosaicos, los transmiten pulgones."]},{"heading":"8.4 · Plagas","body":["El burrito de la frambuesa (Aegorhinus superciliosus) es un curculiónido nativo: el adulto come brotes, pero el daño letal lo hace la larva, que barrena la corona y las raíces principales.","La arañita roja prolifera con calor y polvo, como en hileras junto a caminos de tierra: humedecer los caminos y conservar sus enemigos naturales ayuda a controlarla."]},{"heading":"8.5 · Cosecha","body":["La frambuesa se cosecha cada 2 o 3 días durante la temporada. Para mercado fresco se cosecha temprano en la mañana, sin calor de campo, directamente al envase final para no manipularla de nuevo.","Gran parte de la frambuesa chilena se congela (IQF) para exportación, lo que permite cosechar fruta más madura que para el mercado fresco."]},{"heading":"8.5 · Pre-frío y atmósfera","body":["Su tasa respiratoria es altísima: cada hora a temperatura ambiente acorta su vida. Debe entrar a un túnel de pre-frío (aire forzado a 0 °C) dentro de 2 a 4 horas desde la cosecha.","Durante el transporte se usa atmósfera modificada con CO₂ elevado, que frena la respiración y a Botrytis."]},{"heading":"8.5 · Drosophila suzukii","body":["A diferencia de otras drosófilas, la hembra de D. suzukii tiene un ovipositor aserrado que corta la piel de la fruta sana en maduración. Sus larvas blancas se desarrollan dentro del fruto.","Se maneja con monitoreo con trampas, cosechas frecuentes, eliminación de fruta caída o sobremadura y enfriamiento rápido."]}]'::jsonb, 'bg-thorn-frost', null)
insert into public.modules (id, slug, title, summary, initially_unlocked, codex, bg_theme, sprite_url) values (9, 'horticultura', 'Horticultura e Invernaderos', 'Manejo de hortalizas, ambiente protegido, clima del invernadero y fertirriego.', false, '[{"heading":"9.1 · Tipos de estructura","body":["El microtúnel o túnel bajo cubre una o dos hileras y se usa unas semanas para adelantar cultivos o protegerlos de heladas. El macrotúnel permite trabajar dentro y es común en berries y hortalizas. El invernadero de capilla (dos aguas) y el multicapilla o multitúnel cubren grandes superficies con varias naves unidas.","Más altura significa más volumen de aire: el ambiente cambia de temperatura más lento (mayor inercia térmica) y se ventila mejor. Los invernaderos bajos se calientan muy rápido de día y se enfrían muy rápido de noche."]},{"heading":"9.1 · Materiales de la estructura","body":["En Chile son comunes las estructuras de madera, baratas pero de vida útil corta y con piezas gruesas que dan sombra. El acero galvanizado cuesta más, dura décadas y usa perfiles delgados que sombrean menos.","La estructura debe resistir el viento y, en el sur, la nieve. La orientación de las naves y de las hileras influye en la uniformidad de la luz dentro del invernadero."]},{"heading":"9.1 · Materiales de cubierta","body":["El más usado es el polietileno de baja densidad, de 100 a 200 micrones, con aditivos estabilizadores UV que le dan una vida de una a tres temporadas. El polietileno térmico (con EVA u otros aditivos) retiene el infrarrojo largo y reduce el enfriamiento nocturno; el antigoteo hace que el agua condensada escurra en película en vez de gotear sobre el cultivo; el difusor reparte la luz y evita quemaduras.","El policarbonato y el vidrio duran muchos años y transmiten bien la luz, pero cuestan mucho más. Con el tiempo, el polvo y el envejecimiento bajan la transmisión de luz de cualquier cubierta, por eso se lavan y se renuevan."]},{"heading":"9.2 · El ciclo diario del CO₂","body":["El aire exterior tiene alrededor de 420 ppm de CO₂. De noche, la respiración de las plantas y del suelo lo acumula dentro del invernadero cerrado. Con la salida del sol empieza la fotosíntesis y, si no se ventila, el cultivo puede bajarlo a 200 ppm o menos en pocas horas.","Bajo unas 300 ppm la fotosíntesis cae fuertemente: en un día frío y soleado, con las ventanas cerradas para guardar calor, el CO₂ se vuelve el factor limitante."]},{"heading":"9.2 · Enriquecimiento carbónico","body":["Enriquecer hasta 700 a 1.000 ppm aumenta la fotosíntesis y el rendimiento en cultivos C3 como tomate, pepino y pimiento. Solo conviene mientras las ventanas están cerradas o casi cerradas: con ventilación abierta, el gas se escapa.","Las fuentes son el CO₂ líquido envasado (puro y seguro) y los gases de quemadores de gas natural o propano, que además calientan. La combustión incompleta genera etileno y monóxido de carbono, que dañan al cultivo y a las personas.","Sobre unas 1.500 ppm ya no hay beneficio y pueden aparecer daños; además, el CO₂ se mide con sensores ubicados a la altura del cultivo."]},{"heading":"9.2 · Microclima dentro de la nave","body":["El invernadero no es homogéneo: el aire caliente sube y se estratifica, las zonas cercanas a las ventanas son más frescas y secas, y dentro de un follaje denso el aire queda quieto, húmedo y con menos CO₂.","Los ventiladores de circulación horizontal mueven el aire, uniforman temperatura y humedad, rompen la capa de aire quieto alrededor de las hojas y renuevan el CO₂ que cada hoja consume."]},{"heading":"9.3 · El efecto invernadero","body":["La cubierta deja pasar la radiación solar y retiene parte del calor: de día sube la temperatura y de noche se pierde menos. Los plásticos térmicos (con aditivos que bloquean el infrarrojo largo) reducen el enfriamiento nocturno.","En verano el problema es el exceso de calor: se maneja con ventilación cenital y lateral, mallas sombra, blanqueo de la cubierta y nebulización."]},{"heading":"9.3 · Humedad y DPV","body":["El déficit de presión de vapor (DPV) resume humedad y temperatura. Un DPV muy bajo (aire saturado) frena la transpiración, reduce la absorción de calcio y favorece Botrytis y mildiú; un DPV muy alto estresa y cierra estomas.","Para la mayoría de los cultivos se busca un DPV aproximado de 0,5 a 1,2 kPa. Si la cubierta o las plantas se enfrían bajo el punto de rocío, el agua se condensa y gotea sobre el cultivo."]},{"heading":"9.3 · Control pasivo y activo","body":["El control pasivo usa la propia estructura: ventanas, mallas sombra, blanqueo y pantallas. Ventilar renueva el aire y saca humedad y calor; las ventanas cenitales son más eficientes que las laterales porque el aire caliente sube (efecto chimenea).","El control activo usa energía: calefactores y tubos de agua caliente contra el frío nocturno, ventiladores extractores con paneles evaporativos (pad and fan) o nebulización para enfriar, y pantallas térmicas que de noche se cierran bajo la cubierta para guardar el calor."]},{"heading":"9.4 · Fertirriego","body":["El fertirriego entrega agua y nutrientes juntos por goteo, en pequeñas dosis frecuentes. Se controla midiendo la conductividad eléctrica (CE) y el pH de la solución en el gotero y en el drenaje.","Para tomate en producción se trabaja con CE cercanas a 2-3 dS/m y pH entre 5,5 y 6,5. No se deben mezclar en el mismo estanque calcio con sulfatos o fosfatos, porque precipitan y tapan goteros: se usan estanques A y B separados."]},{"heading":"9.4 · Cultivo sin suelo","body":["En sustratos (fibra de coco, lana de roca, perlita) o en hidroponía pura (NFT, raíz flotante) toda la nutrición depende de la solución. Las ventajas: evita patógenos del suelo, controla mejor la nutrición y logra rendimientos altos.","Se riega con un porcentaje de drenaje (20 a 30 %) para evitar la acumulación de sales en la zona de raíces; si la CE del drenaje sube mucho sobre la del gotero, hay que aumentar el drenaje."]},{"heading":"9.4 · Desórdenes nutricionales típicos","body":["La pudrición apical del tomate y el pimiento es una deficiencia de calcio en el fruto, ligada a riego irregular, alta CE o baja transpiración, más que a falta de calcio en la solución.","El tip burn de la lechuga también es falta de calcio en hojas jóvenes que transpiran poco, en cabezas que crecen muy rápido."]},{"heading":"9.5 · Plagas clave","body":["La mosquita blanca (Trialeurodes vaporariorum y Bemisia tabaci) succiona savia desde el envés, produce mielecilla donde crece fumagina y transmite virus. Los trips (Frankliniella occidentalis) dañan flores y frutos y transmiten el virus del bronceado del tomate (TSWV).","La polilla del tomate (Tuta absoluta) mina hojas, tallos y frutos: es la plaga más importante del tomate en Chile."]},{"heading":"9.5 · Monitoreo y barreras","body":["El monitoreo con trampas adhesivas amarillas (mosquita blanca) y azules (trips), y con feromonas para Tuta absoluta, permite actuar antes de llegar al umbral de daño.","Las mallas antiinsectos en ventanas, la doble puerta, la eliminación de malezas hospederas y de restos de cultivo cortan la entrada y el ciclo de las plagas."]},{"heading":"9.5 · Control biológico","body":["En invernadero el control biológico funciona muy bien porque el ambiente es cerrado: Encarsia formosa parasita ninfas de mosquita blanca; ácaros depredadores como Amblyseius swirskii atacan mosquita blanca y trips; Phytoseiulus persimilis controla arañita roja.","El uso de insecticidas de amplio espectro mata a esos enemigos naturales; por eso el manejo integrado prioriza productos selectivos y rota modos de acción para evitar resistencia."]}]'::jsonb, 'bg-greenhouse', null)
insert into public.modules (id, slug, title, summary, initially_unlocked, codex, bg_theme, sprite_url) values (10, 'aves', 'Reconocimiento de Aves', 'Identificación de aves de Chile, su rol en el agroecosistema y el manejo de daños.', false, '[{"heading":"10.1 · Topografía del ave","body":["Para describir un ave se usan zonas: corona, ceja (supercilio), lorum, garganta, pecho, vientre, dorso, rabadilla, cubiertas alares, plumas primarias y secundarias (remiges) y plumas de la cola (rectrices).","Marcas como una ceja blanca, una banda alar o el color de la rabadilla suelen bastar para separar especies parecidas."]},{"heading":"10.1 · El pico revela la dieta","body":["Pico cónico y grueso: granívoro (chincol, diuca, gorrión). Pico fino y recto: insectívoro (cachudito, golondrina). Pico ganchudo: rapaz o carroñero (tiuque, cernícalo). Pico largo y fino: nectarívoro (picaflor). Pico ancho y aplanado: filtrador (patos).","La forma de las patas también informa: garras fuertes en rapaces, patas palmeadas en aves acuáticas, dedos largos en aves que caminan sobre vegetación flotante."]},{"heading":"10.1 · Más allá de la forma","body":["El dimorfismo sexual puede confundir: el macho de loica tiene el pecho rojo intenso y la hembra es más pálida. Los juveniles a menudo tienen plumajes distintos a los adultos.","El canto, el comportamiento (cómo vuela, si camina o salta), el hábitat y la época del año completan la identificación. Unos binoculares 8x42, una guía de campo y plataformas como eBird ayudan a registrar observaciones con valor científico."]},{"heading":"10.2 · Rapaces diurnas","body":["El tiuque (Milvago chimango) es un falcónido oportunista: come insectos, larvas que deja el arado, roedores y carroña, y es muy común en potreros. El cernícalo (Falco sparverius) es un halcón pequeño que caza insectos y roedores desde perchas o suspendido en el aire.","El peuco (Parabuteo unicinctus), el aguilucho (Geranoaetus polyosoma) y el águila (Geranoaetus melanoleucus) completan el gremio de rapaces diurnas de los campos chilenos."]},{"heading":"10.2 · Rapaces nocturnas","body":["La lechuza (Tyto alba) caza casi exclusivamente roedores: una pareja con polluelos puede consumir miles al año. Entre sus presas está el ratón colilargo, reservorio del virus Hanta.","El tucúquere (Bubo magellanicus) es el búho más grande de Chile; el chuncho (Glaucidium nana) es pequeño y también caza de día.","Las egagrópilas, bolos de pelos y huesos que las rapaces regurgitan, permiten estudiar su dieta sin capturarlas."]},{"heading":"10.2 · Atraerlas al predio","body":["Las cajas nido para lechuzas y las perchas para rapaces diurnas en huertos y viñas aumentan la presión de depredación sobre roedores.","Los rodenticidas anticoagulantes son un riesgo para ellas: una rapaz que come roedores envenenados se intoxica (envenenamiento secundario). El control biológico y los cebos protegidos son la alternativa.","Todas las rapaces están protegidas por la Ley de Caza: está prohibido cazarlas o capturarlas."]},{"heading":"10.3 · Granívoras y frugívoras","body":["El chincol (Zonotrichia capensis), la diuca (Diuca diuca) y la tórtola (Zenaida auriculata) comen semillas y pueden dañar siembras y granos. El tordo (Curaeus curaeus), negro y gregario, forma bandadas en maizales y frutales.","El zorzal (Turdus falcklandii) come lombrices e insectos, pero también fruta madura como cerezas y arándanos. La rara (Phytotoma rara) corta brotes, yemas y hojas tiernas de frutales y hortalizas."]},{"heading":"10.3 · Cuándo y dónde dañan","body":["El daño se concentra en momentos clave: en la siembra, cuando las aves desentierran semillas y plántulas; en el grano lechoso del maíz y del trigo; y en la madurez de la fruta, cuando cerezas, arándanos y uvas toman color y azúcar.","Los bordes del cultivo junto a árboles, cercos y tendidos eléctricos, que sirven de percha y refugio, son los más atacados. Por eso el monitoreo se hace por sectores y en esas fechas críticas."]},{"heading":"10.3 · Especies introducidas","body":["El gorrión (Passer domesticus) llegó desde Europa y se asocia a construcciones humanas. La codorniz (Callipepla californica) fue introducida desde Norteamérica y hoy es especie de caza.","La cotorra argentina (Myiopsitta monachus) es una especie invasora: forma grandes nidos comunales de palitos en árboles y postes de electricidad, y daña frutales y granos."]},{"heading":"10.4 · Cazadoras de insectos","body":["Las golondrinas (la golondrina chilena y la golondrina bermeja, migratoria) cazan insectos en vuelo sobre potreros y cursos de agua. El cachudito y el rayadito buscan insectos entre las ramas; el chercán revisa matorrales y cercos; el fío-fío llega en primavera a alimentarse de insectos y frutos.","En praderas, la loica y el queltehue comen larvas del suelo como el gusano blanco y las cuncunillas; los carpinteros extraen larvas que barrenan la madera. Durante la crianza, una pareja de aves insectívoras captura cientos de insectos al día para sus polluelos."]},{"heading":"10.4 · Picaflores polinizadores","body":["El picaflor chico (Sephanoides sephaniodes) poliniza muchas plantas nativas del centro y sur de Chile, como el chilco, el copihue, el notro y el quintral. El picaflor gigante (Patagona gigas) es el picaflor más grande del mundo y visita flores en la zona central.","El picaflor de Juan Fernández es endémico del archipiélago y está en peligro de extinción."]},{"heading":"10.4 · Flores para aves y cómo atraer aliadas","body":["Las flores polinizadas por aves (ornitofilia) suelen ser tubulares, rojas o anaranjadas, sin aroma y con abundante néctar diluido: las aves ven bien el rojo pero tienen poco olfato, al revés que muchas abejas.","Para atraer aves aliadas al predio se instalan cajas nido para golondrinas y chercanes, se mantienen cercos vivos y bosquetes nativos con flores en distintas épocas y se evitan los insecticidas de amplio espectro, que eliminan su alimento."]},{"heading":"10.5 · El marco legal","body":["En Chile la Ley de Caza (Ley 19.473) y su reglamento definen qué especies se pueden cazar, cuáles están protegidas y cuáles se consideran dañinas. El SAG fiscaliza y otorga permisos especiales cuando una especie protegida causa daños graves.","Cazar, capturar o destruir nidos de especies protegidas sin autorización es un delito, aunque el ave esté dañando un cultivo."]},{"heading":"10.5 · Loros nativos","body":["El choroy (Enicognathus leptorhynchus) es un loro endémico de los bosques del centro-sur: come semillas de araucaria, cereales y fruta, y puede dañar siembras y huertos. El tricahue (Cyanoliseus patagonus) es el loro más grande de Chile y está amenazado por la pérdida de hábitat y la extracción de polluelos.","Ambos son ejemplos de conflicto entre producción y conservación: la solución pasa por métodos de exclusión y ahuyentamiento, no por eliminarlos."]},{"heading":"10.5 · Métodos de manejo","body":["Exclusión: mallas antipájaros sobre cerezos, arándanos o viñas; es el método más eficaz y protege también contra granizo.","Ahuyentamiento: cañones de gas, señales acústicas de alarma, cintas reflectantes, láser y cetrería con halcones. Las aves se acostumbran rápido, por eso hay que rotar métodos y moverlos de lugar.","Manejo del cultivo: sembrar a la profundidad correcta, cosechar a tiempo y evitar dejar grano expuesto reducen la atracción para las bandadas."]}]'::jsonb, 'bg-wheat-storm', null)
insert into public.modules (id, slug, title, summary, initially_unlocked, codex, bg_theme, sprite_url) values (11, 'hongos', 'Reconocimiento y Biología de Hongos', 'Morfología, ciclos de vida, hongos benéficos, fitopatógenos y setas silvestres.', false, '[{"heading":"11.1 · Un reino propio","body":["Los hongos no son plantas: no hacen fotosíntesis y su pared celular es de quitina, no de celulosa. Son heterótrofos que se alimentan por absorción: secretan enzimas al medio y absorben las moléculas digeridas.","Según cómo obtienen su alimento son saprófitos (descomponen materia muerta), parásitos (viven de un hospedero vivo) o simbiontes mutualistas (micorrizas, líquenes)."]},{"heading":"11.1 · Hifas y micelio","body":["El cuerpo de la mayoría de los hongos es un conjunto de filamentos llamados hifas, que en conjunto forman el micelio. Las hifas pueden ser tabicadas (con septos) o cenocíticas (sin tabiques).","Lo que llamamos \"callampa\" o seta es solo el cuerpo fructífero, la estructura que produce esporas; el micelio vive bajo el suelo o dentro de la madera y puede ocupar grandes superficies.","Las levaduras son hongos unicelulares, como Saccharomyces cerevisiae, que fermenta el pan, la cerveza y el vino."]},{"heading":"11.1 · Grandes grupos","body":["Los Ascomycota forman esporas dentro de sacos (ascos): incluyen levaduras, Botrytis, Penicillium, oídios y morchellas. Los Basidiomycota forman esporas en basidios: la mayoría de las setas con sombrero, royas y carbones.","Los oomicetos, como Phytophthora y los mildiús, parecen hongos pero pertenecen a otro grupo (Stramenopila): su pared es de celulosa y por eso responden a fungicidas específicos."]},{"heading":"11.2 · Esporas","body":["Los hongos se dispersan por esporas que viajan con el viento, el agua, los insectos o las herramientas. Las asexuales, como los conidios, se producen en enormes cantidades y causan las epidemias durante la temporada.","Las sexuales (ascosporas, basidiosporas) aportan variabilidad genética, lo que favorece la aparición de resistencia a fungicidas y de nuevas razas."]},{"heading":"11.2 · Ciclos de vida","body":["La infección primaria inicia la enfermedad a partir del inóculo que sobrevivió el invierno; las infecciones secundarias la multiplican durante la temporada. Una enfermedad policíclica, como el oídio o la botritis, tiene muchos ciclos por temporada.","La venturia del manzano (Venturia inaequalis) sobrevive en hojas caídas y libera ascosporas en primavera con lluvia: eliminar o triturar la hoja caída reduce el inóculo primario."]},{"heading":"11.2 · Estructuras de supervivencia","body":["Los esclerocios son masas compactas de micelio que sobreviven años en el suelo (Sclerotinia, Sclerotium). Las clamidosporas son esporas de pared gruesa que resisten condiciones adversas (Fusarium).","Por eso la rotación de cultivos, la sanidad de los restos de cosecha y la semilla limpia son tan importantes como los fungicidas."]},{"heading":"11.3 · Micorrizas","body":["Las micorrizas son asociaciones entre hongos y raíces. Las arbusculares (Glomeromycota) colonizan el interior de las raíces de la mayoría de los cultivos y aumentan la absorción de fósforo, agua y micronutrientes; a cambio reciben azúcares.","Las ectomicorrizas envuelven las raíces de pinos, robles y Nothofagus, y muchas producen setas comestibles. Las ericoides acompañan a arándanos y cranberry.","La labranza intensa, el suelo desnudo y el exceso de fósforo soluble reducen las micorrizas."]},{"heading":"11.3 · Biocontroladores","body":["Trichoderma compite por espacio y nutrientes, parasita a otros hongos (micoparasitismo) y produce antibióticos: se usa contra Botrytis, Rhizoctonia y pudriciones de raíz y cuello.","Los hongos entomopatógenos, como Beauveria bassiana y Metarhizium, infectan insectos a través de la cutícula y se usan como bioinsecticidas."]},{"heading":"11.3 · Descomponedores","body":["Los hongos saprófitos son los principales descomponedores de la lignina y la celulosa: reciclan nutrientes y forman humus. Sin ellos los rastrojos se acumularían por décadas.","Las hifas y la glomalina de las micorrizas pegan las partículas del suelo y estabilizan los agregados."]},{"heading":"11.4 · El triángulo de la enfermedad","body":["Una enfermedad ocurre cuando coinciden un hospedero susceptible, un patógeno virulento y un ambiente favorable, durante el tiempo suficiente. El manejo actúa sobre los tres lados: variedades resistentes, menos inóculo y menos condiciones favorables.","Muchos hongos necesitan agua libre sobre la hoja por varias horas para infectar: por eso los modelos de pronóstico usan horas de mojado y temperatura."]},{"heading":"11.4 · Enfermedades clave","body":["Botrytis cinerea (pudrición gris) ataca flores y frutos de uva, frutilla, frambuesa y arándano, con alta humedad. El oídio forma un polvo blanco sobre hojas y bayas y, a diferencia de la mayoría, no necesita agua libre: le basta la humedad ambiental.","Las royas forman pústulas de color óxido (trigo, poroto, ajo); algunas necesitan dos hospederos distintos para completar su ciclo. Fusarium y Verticillium tapan los vasos del xilema y causan marchitez."]},{"heading":"11.4 · Manejo","body":["Los fungicidas preventivos (de contacto, como cobre o captan) protegen la superficie antes de la infección; los sistémicos penetran y pueden detener infecciones recientes, pero tienen alto riesgo de resistencia si se repite el mismo modo de acción.","La clasificación FRAC agrupa los fungicidas por modo de acción para planificar rotaciones. La poda que ventila, la eliminación de restos enfermos y el riego que no moja el follaje completan el manejo integrado."]},{"heading":"11.5 · Hongos comestibles nativos","body":["El digüeñe (Cyttaria espinosae) es un hongo parásito del roble y el hualle: forma cuerpos fructíferos anaranjados con alvéolos en primavera. El changle (Ramaria flava) es coraloide y amarillo, y crece en bosques de Nothofagus en otoño.","El loyo (Boletus loyo) es un boleto con poros en vez de láminas; el gargal (Grifola gargal) crece sobre troncos. La recolección de estas especies es un saber tradicional del pueblo mapuche y del campesinado del sur."]},{"heading":"11.5 · Hongos de plantaciones","body":["En las plantaciones de pino crecen Suillus luteus (callampa de pino, con poros y sombrero viscoso) y Lactarius deliciosus (exuda un látex anaranjado). Ambos son ectomicorrícicos y llegaron con los pinos.","La morchella (Morchella), de sombrero alveolado, se recolecta y exporta deshidratada."]},{"heading":"11.5 · Especies tóxicas","body":["Amanita phalloides, introducida en Chile junto a robles y encinos europeos, contiene amatoxinas que destruyen el hígado; los síntomas aparecen 6 a 24 horas después, cuando el daño ya avanzó. Amanita muscaria, de sombrero rojo con verrugas blancas, también es tóxica.","Las Amanita tienen láminas blancas, anillo y una volva (bolsa) en la base del pie: si el pie no se desentierra, la volva queda oculta. La regla es simple: nunca consumir un hongo silvestre sin identificación segura por un experto. No existen \"pruebas caseras\" (plata, ajo, animales) que indiquen si un hongo es comestible."]}]'::jsonb, 'bg-spore-crypt', null)
insert into public.modules (id, slug, title, summary, initially_unlocked, codex, bg_theme, sprite_url) values (12, 'avicola', 'Producción Avícola', 'Razas, nutrición, sanidad, bienestar y manejo de galpones.', false, '[{"heading":"12.1 · La recría","body":["La recría va desde el día de nacida hasta cerca de las 16 a 18 semanas, cuando la pollita pasa al galpón de postura. En esta etapa se forma el esqueleto, la musculatura y el aparato digestivo que sostendrán un año completo de producción.","La meta es seguir la curva de peso de la línea genética y lograr un lote uniforme: se pesa una muestra cada semana y se busca que al menos 80 a 85 % de las aves esté dentro de ±10 % del peso promedio. Un lote disparejo entra a postura de forma escalonada y rinde menos."]},{"heading":"12.1 · Luz y madurez sexual","body":["La gallina responde al largo del día: los días que se alargan estimulan la madurez sexual. Por eso en la recría se usan días cortos y constantes (unas 8 a 10 horas) y nunca se alargan, para que la pollita no madure antes de tener el peso adecuado.","Cuando el lote alcanza el peso objetivo se fotoestimula: se aumenta la luz de forma gradual, por ejemplo una hora la primera semana y luego 15 a 30 minutos por semana, hasta unas 16 horas. Estimular pollitas livianas da huevos pequeños, prolapsos y una postura que no se sostiene."]},{"heading":"12.1 · La curva de postura","body":["La postura parte cerca de las 18 a 20 semanas (5 % de postura), sube rápido y llega al peak, sobre 93 a 95 % en líneas modernas, alrededor de las 26 a 30 semanas. Luego baja lentamente: una buena persistencia mantiene más de 80 % hasta pasadas las 60 semanas.","El peso del huevo aumenta con la edad, mientras la calidad de la cáscara empeora. Comparar la curva real con el estándar de la línea permite detectar a tiempo problemas de alimentación, luz o sanidad."]},{"heading":"12.2 · Energía y proteína","body":["Las aves comen principalmente para cubrir su requerimiento de energía, que se expresa como energía metabolizable (kcal/kg). El maíz es la principal fuente energética y la harina de soya, la principal fuente de proteína.","Más que la proteína total importan los aminoácidos esenciales: la metionina es el primer limitante en dietas maíz-soya, seguida de la lisina. Se agregan en forma sintética para no sobrecargar de proteína la dieta."]},{"heading":"12.2 · Dietas por etapa","body":["Los broilers reciben dietas de inicio, crecimiento y terminación, con proteína decreciente a medida que crecen. Las ponedoras pasan por recría y luego postura.","La ponedora necesita mucho calcio (alrededor de 3,5 a 4,5 % de la dieta), idealmente con parte en partículas gruesas (conchilla), que se disuelven lentamente durante la noche, cuando se forma la cáscara."]},{"heading":"12.2 · Agua y calidad del alimento","body":["Las aves beben aproximadamente el doble de agua que el alimento que consumen, y más con calor. Una caída del consumo de agua suele ser la primera señal de enfermedad.","Las micotoxinas (aflatoxinas, por ejemplo) de granos mal almacenados dañan el hígado, la inmunidad y la producción: el grano debe guardarse seco y se usan secuestrantes."]},{"heading":"12.3 · Crianza y temperatura","body":["Los pollitos no regulan bien su temperatura durante las primeras semanas: necesitan cerca de 32-35 °C al nivel del ave en la primera semana, y luego unos 3 °C menos por semana hasta llegar a 20-22 °C.","El comportamiento indica si la temperatura es correcta: amontonados bajo la fuente de calor tienen frío; alejados, jadeando y con alas abiertas tienen calor; repartidos de forma pareja están cómodos."]},{"heading":"12.3 · Ventilación y amoníaco","body":["La ventilación saca humedad, calor, CO₂ y amoníaco. El amoníaco se forma en una cama húmeda a partir de las deyecciones: sobre unos 20-25 ppm irrita ojos y vías respiratorias y favorece enfermedades.","Una cama húmeda y apelmazada además causa lesiones en las patas (pododermatitis) y en la pechuga. Bebederos sin fugas, buena ventilación y densidades adecuadas la mantienen seca."]},{"heading":"12.3 · Sistemas productivos","body":["Los broilers (Ross, Cobb) se crían en galpones sobre cama y llegan a unos 2,5 a 3 kg en cerca de 40 a 42 días, con una conversión alimenticia de 1,5 a 1,7 kg de alimento por kg de peso vivo. Las ponedoras se crían en jaulas convencionales, jaulas enriquecidas, sistemas libres de jaula en piso o aviario, o al aire libre (free range).","La tendencia del mercado y de la regulación es hacia sistemas libres de jaula, que mejoran el bienestar pero exigen más espacio y manejo sanitario. En los sistemas campesinos se crían razas de doble propósito y la collonca, la gallina mapuche de huevos azules."]},{"heading":"12.4 · Enfermedades de importancia","body":["La influenza aviar de alta patogenicidad y la enfermedad de Newcastle son de denuncia obligatoria al SAG: causan alta mortalidad y restricciones al comercio. Las aves silvestres migratorias pueden introducir la influenza aviar, como ocurrió en Chile en 2022-2023.","La enfermedad de Marek, causada por un herpesvirus, produce tumores y parálisis; se vacuna en la incubadora o al día de edad. La bronquitis infecciosa y el Gumboro (bursitis infecciosa) también se previenen con vacunas."]},{"heading":"12.4 · Coccidiosis","body":["La coccidiosis la causan protozoos del género Eimeria, que dañan el intestino: diarrea, a veces con sangre, y mala conversión. Prospera en camas húmedas.","Se controla con anticoccidiales en el alimento, vacunas y, sobre todo, manteniendo la cama seca."]},{"heading":"12.4 · Bioseguridad","body":["Es el conjunto de medidas para que los patógenos no entren ni salgan del plantel: cercos, control de visitas, cambio de ropa y calzado, pediluvios, desinfección de vehículos, control de roedores y aves silvestres, y agua potable.","El sistema \"todo dentro, todo fuera\" cría lotes de una sola edad, y entre lotes se limpia, desinfecta y deja un vacío sanitario. Mezclar edades mantiene los patógenos circulando."]},{"heading":"12.5 · Formación y calidad del huevo","body":["El huevo tarda unas 24-26 horas en formarse en el oviducto, de las cuales cerca de 20 corresponden a la cáscara en el útero. Por eso la gallina pone aproximadamente un huevo al día.","La calidad interna se mide en unidades Haugh (altura de la clara densa en relación al peso): baja con la edad del huevo y con temperaturas altas de almacenaje. El color de la yema depende de los pigmentos (xantofilas) de la dieta, no del valor nutritivo.","El color de la cáscara depende de la línea genética: no cambia el valor nutritivo del huevo."]},{"heading":"12.5 · Muda y ciclo productivo","body":["Después de unas 70-80 semanas la postura y la calidad de cáscara bajan. La muda natural renueva plumas y el aparato reproductor; las mudas inducidas por ayuno prolongado están cuestionadas o prohibidas por razones de bienestar."]},{"heading":"12.5 · Bienestar animal","body":["Las cinco libertades: libres de hambre y sed; de incomodidad; de dolor, lesiones y enfermedad; libres para expresar su comportamiento normal; y libres de miedo y angustia.","El picaje (las aves se picotean plumas y piel) aparece con alta densidad, exceso de luz, dietas pobres en aminoácidos azufrados, aburrimiento o falta de material para escarbar. Se previene con enriquecimiento ambiental, perchas, nidos, baños de polvo y dietas balanceadas."]}]'::jsonb, 'bg-mutant-coop', null)
insert into public.modules (id, slug, title, summary, initially_unlocked, codex, bg_theme, sprite_url) values (13, 'caprinos', 'Producción Caprina y Rumiantes Menores', 'Manejo reproductivo, alimentación en secano, sanidad y productos lácteos.', false, '[{"heading":"13.1 · La caprinocultura en Chile","body":["La mayor parte de las cabras de Chile está en el secano del Norte Chico, con la región de Coquimbo como principal zona caprina. Predomina la crianza campesina de cabras criollas, rústicas y adaptadas a la escasez de forraje.","Muchos crianceros practican la trashumancia: en verano suben con el rebaño a las veranadas cordilleranas y en invierno vuelven a los valles y al secano costero."]},{"heading":"13.1 · Razas","body":["Lecheras: Saanen (blanca, la más productiva), Alpina, Toggenburg y Anglo-Nubian (orejas largas y caídas, leche con más grasa). Carne: Boer, de origen sudafricano, con gran desarrollo muscular.","El cruzamiento de cabras criollas con machos de razas lecheras o Boer aumenta la producción, pero los cruzas exigen mejor alimentación y sanidad que la criolla."]},{"heading":"13.1 · Ovinos y otros rumiantes menores","body":["Los ovinos dominan en la Patagonia (Magallanes, con razas como Corriedale y Merino para lana y carne) y en el centro-sur con razas de carne como Suffolk.","Cabras y ovejas difieren en su conducta alimentaria: la oveja pastorea pasto bajo, mientras que la cabra ramonea hojas y brotes de arbustos, lo que le permite aprovechar matorrales que otras especies no usan."]},{"heading":"13.2 · El rumen","body":["Los rumiantes tienen un estómago de cuatro compartimentos: rumen, retículo, omaso y abomaso (cuajar, el estómago \"verdadero\"). En el rumen, bacterias, protozoos y hongos fermentan la fibra y producen ácidos grasos volátiles, la principal fuente de energía del animal.","Los microorganismos también sintetizan proteína microbiana a partir del nitrógeno de la dieta, incluso de fuentes no proteicas como la urea, y vitaminas del complejo B."]},{"heading":"13.2 · Fibra y acidosis","body":["La fibra estimula la rumia y la saliva, que contiene bicarbonato y amortigua el pH del rumen. Una dieta con mucho grano y poca fibra fermenta rápido, acumula ácido láctico y baja el pH bajo 5,5: es la acidosis ruminal, que causa diarrea, cojeras e incluso la muerte.","Los cambios de dieta deben hacerse de forma gradual, durante una o dos semanas, para que la flora ruminal se adapte."]},{"heading":"13.2 · Alimentación en el secano","body":["En el secano la disponibilidad de forraje sigue a las lluvias: abundante en invierno-primavera y escasa en verano-otoño. Las estrategias incluyen guardar heno, usar arbustos forrajeros como el atriplex, rastrojos de cultivos y suplementar en los periodos críticos.","Los requerimientos más altos están en el último tercio de la gestación y en la lactancia: una cabra mal alimentada en esos momentos tiene crías débiles y poca leche."]},{"heading":"13.3 · Estacionalidad","body":["La cabra es una reproductora estacional de días cortos: su actividad sexual se concentra en otoño, cuando los días se acortan. Por eso la mayoría de los partos ocurre a fines de invierno y en primavera, cuando hay más forraje.","El ciclo estral dura unos 21 días y el celo de 24 a 36 horas; la gestación dura alrededor de 150 días (cinco meses)."]},{"heading":"13.3 · Efecto macho y manejo","body":["Si el macho se mantiene separado de las hembras y luego se reintroduce al comienzo de la temporada, su olor estimula la ovulación y sincroniza los celos: es el efecto macho. También se usan tratamientos hormonales y programas de luz para producir fuera de temporada.","Un macho puede servir a unas 30 a 50 hembras en monta natural. Conviene registrar los encastes para conocer las fechas de parto."]},{"heading":"13.3 · Parto y calostro","body":["El cabrito debe tomar calostro en sus primeras horas de vida: es su única fuente de anticuerpos, porque la placenta no los transfiere. La capacidad del intestino para absorberlos cae rápidamente después de las primeras 12 a 24 horas.","En lecherías los cabritos se separan y se crían con calostro tratado y sustituto lácteo, una práctica que también ayuda a cortar la transmisión de la artritis encefalitis caprina."]},{"heading":"13.4 · Parásitos gastrointestinales","body":["Haemonchus contortus es un nematodo que vive en el abomaso y se alimenta de sangre: causa anemia, edema submandibular (\"papada de botella\") y muerte, sobre todo en primaveras húmedas.","El método FAMACHA compara el color de la mucosa del ojo con una tarjeta: solo se desparasita a los animales pálidos. Así se reduce el uso de antiparasitarios y se frena la resistencia, que ya es un problema serio."]},{"heading":"13.4 · Enfermedades infecciosas","body":["La artritis encefalitis caprina (CAE) es un lentivirus que se transmite sobre todo por el calostro y la leche: causa artritis, mastitis indurada y encefalitis en cabritos. No tiene cura; se controla con diagnóstico y separación de crías.","La linfadenitis caseosa (Corynebacterium pseudotuberculosis) forma abscesos en los ganglios con pus espeso; se contagia por heridas de esquila o descorne y por el pus de abscesos que se rompen.","La brucelosis caprina (Brucella melitensis) causa abortos y es una zoonosis grave, transmitida a las personas por leche y quesos sin pasteurizar: es de denuncia obligatoria al SAG."]},{"heading":"13.4 · Mastitis y manejo sanitario","body":["La mastitis es la inflamación de la ubre, casi siempre bacteriana. El California Mastitis Test (CMT) detecta mastitis subclínica en la leche. La higiene de la ordeña y el sellado de pezones la previenen.","Un calendario sanitario incluye vacunación contra clostridiales (enterotoxemia), control de parásitos con FAMACHA, cuarentena de animales nuevos y despezuñe periódico."]},{"heading":"13.5 · La leche de cabra","body":["Tiene glóbulos de grasa más pequeños que la de vaca y una proporción mayor de ácidos grasos de cadena media (caproico, caprílico y cáprico), responsables de su sabor característico.","Las cabras transforman casi todo el betacaroteno en vitamina A: por eso su leche y sus quesos son más blancos que los de vaca. Una cabra criolla produce poca leche en lactancias cortas; una Saanen bien alimentada puede producir varios litros diarios."]},{"heading":"13.5 · Higiene y pasteurización","body":["La calidad se mide por el recuento de células somáticas (indicador de mastitis) y el recuento bacteriano. Una ordeña higiénica y el enfriamiento rápido de la leche son esenciales.","La pasteurización (por ejemplo, 72 °C por 15 segundos o 63 °C por 30 minutos) elimina patógenos como Brucella y Listeria. El queso de leche cruda es un riesgo real de brucelosis y listeriosis."]},{"heading":"13.5 · Elaboración de quesos","body":["El queso se obtiene coagulando la caseína con cuajo (quimosina) o con acidez; luego se corta la cuajada, se desuera, se sala, se moldea, se prensa y, en algunos casos, se madura.","El queso de cabra fresco es tradicional en el Norte Chico. La formalización de queserías campesinas con resolución sanitaria y leche pasteurizada abre mercados formales y protege la salud de los consumidores."]}]'::jsonb, 'bg-dry-steppe', null)
insert into public.submodules (id, module_id, sort_order, title, description, subboss_name, subboss_title, subboss_max_hp, subboss_damage_per_hit) values ('m1-s1', 1, 1, 'Textura y Estructura', 'Arena, limo y arcilla: cómo se miden y cómo se agrupan en agregados que sostienen raíces, agua y aire.', 'Densímetro de Bouyoucos', 'Lector de la Sedimentación', 40, 10)
insert into public.submodules (id, module_id, sort_order, title, description, subboss_name, subboss_title, subboss_max_hp, subboss_damage_per_hit) values ('m1-s2', 1, 2, 'Retención y Curvas de Humedad', 'Capacidad de campo, punto de marchitez y la curva que une humedad con tensión: la base para decidir cuándo y cuánto regar.', 'Olla de Presión Richards', 'Extractora de la Tensión Mátrica', 40, 10)
insert into public.submodules (id, module_id, sort_order, title, description, subboss_name, subboss_title, subboss_max_hp, subboss_damage_per_hit) values ('m1-s3', 1, 3, 'Aireación y Compactación', 'Densidad aparente, porosidad y resistencia a la penetración: cuándo el suelo deja de respirar y cómo recuperarlo.', 'Penitente del Suelo Fisurado', 'Guardián del Pie de Arado', 40, 10)
insert into public.submodules (id, module_id, sort_order, title, description, subboss_name, subboss_title, subboss_max_hp, subboss_damage_per_hit) values ('m1-s4', 1, 4, 'Erosión y Conservación', 'Cómo el agua y el viento arrancan el suelo, cómo estimar la pérdida con la USLE y qué prácticas la frenan.', 'Vórtice de Acarreo', 'Devorador de Laderas', 40, 10)
insert into public.submodules (id, module_id, sort_order, title, description, subboss_name, subboss_title, subboss_max_hp, subboss_damage_per_hit) values ('m1-s5', 1, 5, 'Horizontes y Perfil de Suelo', 'Leer una calicata: horizontes, color, moteados y los factores que forman los suelos de Chile.', 'Espectro de la Calicata Profunda', 'Guardián de los Horizontes', 50, 10)
insert into public.submodules (id, module_id, sort_order, title, description, subboss_name, subboss_title, subboss_max_hp, subboss_damage_per_hit) values ('m2-s1', 2, 1, 'CIC y Coloides del Suelo', 'Arcillas, humus y la capacidad de intercambio catiónico: la despensa que retiene los nutrientes.', 'Coloso de Adsorción', 'Devorador de Cationes', 40, 10)
insert into public.submodules (id, module_id, sort_order, title, description, subboss_name, subboss_title, subboss_max_hp, subboss_damage_per_hit) values ('m2-s2', 2, 2, 'pH, Encalado y Disponibilidad', 'La acidez del suelo, el aluminio tóxico y cómo el pH abre o cierra la puerta a cada nutriente.', 'Alquimista Acidófilo', 'Señor del Aluminio Tóxico', 40, 10)
insert into public.submodules (id, module_id, sort_order, title, description, subboss_name, subboss_title, subboss_max_hp, subboss_damage_per_hit) values ('m2-s3', 2, 3, 'Nitrógeno, Fósforo y Potasio', 'Los tres macronutrientes primarios: su ciclo en el suelo, sus pérdidas y cómo los usa la planta.', 'Hidra del Nitrato Lixiviado', 'Fugitiva del Perfil', 40, 10)
insert into public.submodules (id, module_id, sort_order, title, description, subboss_name, subboss_title, subboss_max_hp, subboss_damage_per_hit) values ('m2-s4', 2, 4, 'Secundarios y Micronutrientes', 'Calcio, magnesio y azufre, y los micronutrientes que faltan en poca cantidad pero frenan todo el cultivo.', 'Sombras Cloróticas', 'Heraldos de la Carencia', 40, 10)
insert into public.submodules (id, module_id, sort_order, title, description, subboss_name, subboss_title, subboss_max_hp, subboss_damage_per_hit) values ('m2-s5', 2, 5, 'Diagnóstico y Programas de Fertilización', 'Análisis de suelo y foliar, balance de nutrientes y salinidad: cómo decidir cuánto, cuándo y con qué fertilizar.', 'Auditor de Espectrometría', 'Juez de los Rangos Críticos', 50, 10)
insert into public.submodules (id, module_id, sort_order, title, description, subboss_name, subboss_title, subboss_max_hp, subboss_damage_per_hit) values ('m3-s1', 3, 1, 'Radiación y Balance de Energía', 'Onda corta, onda larga, albedo y radiación neta: la energía que mueve la fotosíntesis y el clima del huerto.', 'Prisma Solar Descalibrado', 'Ladrón de Onda Larga', 40, 10)
insert into public.submodules (id, module_id, sort_order, title, description, subboss_name, subboss_title, subboss_max_hp, subboss_damage_per_hit) values ('m3-s2', 3, 2, 'Temperatura, Grados Día y Horas Frío', 'Cómo la temperatura marca el ritmo del cultivo: sumas térmicas para crecer y frío invernal para despertar.', 'Criomante del Meristema', 'Contador de Horas Frío', 40, 10)
insert into public.submodules (id, module_id, sort_order, title, description, subboss_name, subboss_title, subboss_max_hp, subboss_damage_per_hit) values ('m3-s3', 3, 3, 'Heladas: Tipos y Control', 'Heladas radiativas y advectivas, la inversión térmica y los métodos activos y pasivos para proteger el huerto.', 'El Inversor Térmico', 'Señor de la Noche Despejada', 40, 10)
insert into public.submodules (id, module_id, sort_order, title, description, subboss_name, subboss_title, subboss_max_hp, subboss_damage_per_hit) values ('m3-s4', 3, 4, 'Humedad, Viento y Evapotranspiración', 'Del vapor de agua en el aire a la ET de referencia: cuánta agua pide la atmósfera y cuánta usa el cultivo.', 'Viento Psicrométrico', 'Amo de la ET₀', 40, 10)
insert into public.submodules (id, module_id, sort_order, title, description, subboss_name, subboss_title, subboss_max_hp, subboss_damage_per_hit) values ('m3-s5', 3, 5, 'Clima de Chile y Riesgo Agroclimático', 'Los climas del país, El Niño y La Niña, la sequía y el cambio climático en la planificación agrícola.', 'Autómata de la Caseta Meteorológica', 'Vigía del Riesgo Climático', 50, 10)
insert into public.submodules (id, module_id, sort_order, title, description, subboss_name, subboss_title, subboss_max_hp, subboss_damage_per_hit) values ('m4-s1', 4, 1, 'Fotosíntesis C3, C4 y CAM', 'Cómo la planta convierte luz en azúcares, la fotorrespiración y las tres estrategias para fijar carbono.', 'Guardián del Complejo Antena', 'Escudo de Clorofila', 40, 10)
insert into public.submodules (id, module_id, sort_order, title, description, subboss_name, subboss_title, subboss_max_hp, subboss_damage_per_hit) values ('m4-s2', 4, 2, 'Agua en la Planta: Potencial Hídrico', 'El potencial hídrico, el camino del agua del suelo a la atmósfera y cómo se mide el estrés en terreno.', 'Tensión Xilemática Extrema', 'Medidor del Potencial Hídrico', 40, 10)
insert into public.submodules (id, module_id, sort_order, title, description, subboss_name, subboss_title, subboss_max_hp, subboss_damage_per_hit) values ('m4-s3', 4, 3, 'Transpiración y Estomas', 'Cómo la planta equilibra la entrada de CO₂ con la pérdida de agua: la regulación de los estomas.', 'Sombra Osmótica', 'Emisaria del Ácido Abscísico', 40, 10)
insert into public.submodules (id, module_id, sort_order, title, description, subboss_name, subboss_title, subboss_max_hp, subboss_damage_per_hit) values ('m4-s4', 4, 4, 'Hormonas Vegetales', 'Auxinas, giberelinas, citoquininas, etileno y ABA: las señales que coordinan crecimiento, cuaja y maduración.', 'Quimera de Apicalidad', 'Bestia de la Dominancia Apical', 40, 10)
insert into public.submodules (id, module_id, sort_order, title, description, subboss_name, subboss_title, subboss_max_hp, subboss_damage_per_hit) values ('m4-s5', 4, 5, 'Partición de Asimilados', 'Fuentes y sumideros: hacia dónde viajan los azúcares y por qué la carga frutal decide la cosecha siguiente.', 'Dren de Azúcares', 'Vampiro del Añerismo', 50, 10)
insert into public.submodules (id, module_id, sort_order, title, description, subboss_name, subboss_title, subboss_max_hp, subboss_damage_per_hit) values ('m5-s1', 5, 1, 'Raíz, Tallo y Hoja', 'La morfología vegetativa: tipos de raíz, tallos modificados y las partes de la hoja que sirven para identificar.', 'El Meristema Bifurcado', 'Arquitecto de Raíz, Tallo y Hoja', 40, 10)
insert into public.submodules (id, module_id, sort_order, title, description, subboss_name, subboss_title, subboss_max_hp, subboss_damage_per_hit) values ('m5-s2', 5, 2, 'Morfología Floral', 'Las piezas de la flor, la posición del ovario, las inflorescencias y la sexualidad de las plantas.', 'Flor de Sépalos Caducos', 'Bruja del Ovario Ínfero', 40, 10)
