  ('m2-s5-q2', 2, 'm2-s5', '¿En qué unidad se mide la conductividad eléctrica?', 'dS/m', array['cmol(+)/kg', 'g/cm³', 'kPa']::text[], false, 22),
  ('m2-s5-q3', 2, 'm2-s5', '¿Qué resume el concepto de las "4 R"?', 'Fuente, dosis, momento y lugar correctos', array['Riego, rotación, rastrojo y rendimiento', 'Las cuatro estaciones del año', 'Los cuatro macronutrientes']::text[], false, 23),
  ('m2-s5-q4', 2, 'm2-s5', '¿Cómo se manejan las sales que el riego acumula en la zona de raíces?', 'Con una fracción de lavado', array['Con más fertilizante potásico', 'Regando menos', 'Aplicando urea']::text[], false, 24),
  ('m2-s5-q5', 2, 'm2-s5', '¿Qué mide el índice salino de un fertilizante?', 'Cuánto aumenta la CE de la solución del suelo', array['Cuánto sodio aporta al complejo de intercambio', 'Qué fracción del producto es nutriente puro', 'Con qué rapidez se disuelve en el agua']::text[], false, 25),
  ('m2-boss', 2, null, 'Un huerto regado con agua de CE 2,5 dS/m muestra quemado de bordes en hojas viejas, CE del suelo sobre el umbral y PSI normal. ¿Cuál es el manejo correcto?', 'Aumentar la fracción de lavado y preferir fertilizantes de bajo índice salino', array['Aplicar yeso para desplazar el sodio, aunque el PSI sea normal', 'Encalar para subir el pH y precipitar las sales del suelo', 'Reducir el riego para que la planta absorba menos sales']::text[], true, 999),
  ('m3-s1-q1', 3, 'm3-s1', '¿Qué rango corresponde a la radiación fotosintéticamente activa (PAR)?', '400 a 700 nm', array['100 a 300 nm', '700 a 1.000 nm', '3 a 50 µm']::text[], false, 1),
  ('m3-s1-q2', 3, 'm3-s1', '¿Qué es el albedo?', 'La fracción de radiación de onda corta reflejada', array['La radiación absorbida de noche', 'La temperatura del suelo', 'La humedad del aire']::text[], false, 2),
  ('m3-s1-q3', 3, 'm3-s1', '¿Qué superficie tiene el albedo más alto?', 'Nieve fresca', array['Suelo oscuro húmedo', 'Cultivo verde', 'Agua profunda']::text[], false, 3),
  ('m3-s1-q4', 3, 'm3-s1', '¿En qué se usa la mayor parte de la radiación neta de un cultivo bien regado?', 'En calor latente (evapotranspiración)', array['En calor sensible (calentar el aire)', 'En flujo de calor hacia el suelo', 'En radiación reflejada (albedo)']::text[], false, 4),
  ('m3-s1-q5', 3, 'm3-s1', '¿Qué tipo de radiación emiten el suelo y las plantas?', 'Onda larga (infrarrojo térmico)', array['Onda corta visible (PAR)', 'Ultravioleta (UV-B)', 'Onda corta infrarroja cercana']::text[], false, 5),
  ('m3-s2-q1', 3, 'm3-s2', '¿Qué umbral define una hora frío en el modelo clásico?', 'Una hora bajo 7,2 °C', array['Una hora bajo 0 °C', 'Una hora bajo 15 °C', 'Una hora con helada']::text[], false, 6),
  ('m3-s2-q2', 3, 'm3-s2', '¿Qué pasa si un frutal caduco no acumula suficiente frío?', 'Brota y florece tarde y desuniforme', array['Florece antes de tiempo', 'Aumenta el calibre', 'Pierde las raíces']::text[], false, 7),
  ('m3-s2-q3', 3, 'm3-s2', '¿Qué producto se usa como compensador de frío?', 'Cianamida hidrogenada', array['Urea', 'Ácido giberélico', 'Sulfato de cobre']::text[], false, 8),
  ('m3-s2-q4', 3, 'm3-s2', '¿Para qué plaga se usan grados día en el monitoreo?', 'Polilla de la manzana', array['Oídio del manzano', 'Botrytis de la vid', 'Nematodo agallador']::text[], false, 9),
  ('m3-s2-q5', 3, 'm3-s2', '¿A qué altura se mide la temperatura del aire en una estación meteorológica?', 'Entre 1,5 y 2 m, en garita a la sombra', array['A ras de suelo, en garita a la sombra', 'Entre 1,5 y 2 m, al sol directo', 'A 10 m, sobre una torre al sol']::text[], false, 10),
  ('m3-s3-q1', 3, 'm3-s3', '¿Qué fenómeno ocurre en una helada radiativa?', 'Inversión térmica: aire más cálido sobre el aire frío del suelo', array['Advección: una masa de aire polar entra con viento', 'Convección: el aire frío sube y el cálido baja', 'Nubosidad baja que atrapa el aire frío junto al suelo']::text[], false, 11),
  ('m3-s3-q2', 3, 'm3-s3', '¿Por qué la helada negra suele ser más dañina?', 'El aire seco no forma escarcha ni libera calor latente', array['Ocurre con viento fuerte que impide controlarla', 'La escarcha bloquea la luz y quema las hojas', 'Siempre viene acompañada de granizo y lluvia']::text[], false, 12),
