  ('m13-s3-q5', 13, 'm13-s3', '¿Cuánto dura aproximadamente el ciclo estral de la cabra?', 'Unos 21 días', array['Unos 5 días', 'Unos 60 días', 'Unos 150 días']::text[], false, 15),
  ('m13-s4-q1', 13, 'm13-s4', '¿Qué evalúa el método FAMACHA?', 'El color de la mucosa del ojo para detectar anemia', array['El peso vivo del animal para dosificar', 'La calidad de la leche por su color', 'El largo de la pezuña para despezuñar']::text[], false, 16),
  ('m13-s4-q2', 13, 'm13-s4', '¿Cómo se transmite principalmente la artritis encefalitis caprina (CAE)?', 'Por calostro y leche', array['Por picadura de mosquito', 'Por el agua de riego', 'Por el viento']::text[], false, 17),
  ('m13-s4-q3', 13, 'm13-s4', '¿Qué produce la linfadenitis caseosa?', 'Abscesos en los ganglios con pus espeso', array['Clorosis en las mucosas', 'Diarrea con sangre en cabritos', 'Ceguera y caída del pelo']::text[], false, 18),
  ('m13-s4-q4', 13, 'm13-s4', '¿Por qué la brucelosis caprina es tan importante en salud pública?', 'Es una zoonosis transmitida por leche y quesos sin pasteurizar', array['Solo afecta a las aves y no a los rumiantes', 'No afecta a las personas ni al comercio', 'Se cura sola en pocos días sin tratamiento']::text[], false, 19),
  ('m13-s4-q5', 13, 'm13-s4', '¿Qué test detecta mastitis subclínica en la leche?', 'California Mastitis Test (CMT)', array['Método FAMACHA', 'Test de yodo-almidón', 'Unidades Haugh']::text[], false, 20),
  ('m13-s5-q1', 13, 'm13-s5', '¿Por qué los quesos de cabra son más blancos que los de vaca?', 'La cabra transforma el betacaroteno en vitamina A', array['Porque la leche se blanquea con cloro', 'Porque la leche de cabra tiene más grasa', 'Porque se elaboran solo con suero']::text[], false, 21),
  ('m13-s5-q2', 13, 'm13-s5', '¿Qué indica un recuento de células somáticas alto en la leche?', 'Mastitis', array['Buena higiene', 'Exceso de grasa', 'Leche pasteurizada']::text[], false, 22),
  ('m13-s5-q3', 13, 'm13-s5', '¿Qué enzima del cuajo coagula la caseína?', 'Quimosina', array['Amilasa', 'Ureasa', 'Lipasa']::text[], false, 23),
  ('m13-s5-q4', 13, 'm13-s5', '¿Qué patógenos elimina la pasteurización?', 'Brucella y Listeria, entre otros', array['Ninguno', 'Solo virus de plantas', 'Solo levaduras del pan']::text[], false, 24),
  ('m13-s5-q5', 13, 'm13-s5', '¿Qué ácidos grasos dan el sabor característico a la leche de cabra?', 'Caproico, caprílico y cáprico', array['Oleico y linoleico solamente', 'Ácido láctico', 'Ácido cítrico']::text[], false, 25),
  ('m13-boss', 13, null, 'En un rebaño de secano aparecen abortos en el último tercio de gestación y un criancero con fiebre ondulante que consume queso de leche cruda. ¿Qué se sospecha y qué corresponde?', 'Brucelosis caprina: denunciar al SAG, derivar a la persona a salud y pasteurizar la leche', array['Haemonchosis: desparasitar a todo el rebaño de inmediato', 'Acidosis ruminal: retirar el grano y dar más heno', 'Mastitis: aplicar CMT y seguir vendiendo el queso']::text[], true, 999)
