update public.submodule_progress sp set fight_question_ids = '{}', fight_answered_ids = '{}', subboss_damage = 0 where sp.subboss_defeated_at is null and exists (select 1 from unnest(sp.fight_question_ids) i where not exists (select 1 from public.questions q where q.id = i));
update public.raid_sessions rs set question_ids = array(select i from unnest(rs.question_ids) i where exists (select 1 from public.questions q where q.id = i)), answered_ids = array(select i from unnest(rs.answered_ids) i where exists (select 1 from public.questions q where q.id = i)) where exists (select 1 from unnest(rs.question_ids) i where not exists (select 1 from public.questions q where q.id = i));
-- Las respuestas siguen a su pregunta si esta cambió de módulo.
update public.answers a set module_id = q.module_id from public.questions q where q.id = a.question_id and a.module_id <> q.module_id;

-- Jefes (el HP actual y la derrota se preservan al re-ejecutar)
  on conflict (id) do update set module_id = excluded.module_id, name = excluded.name, title = excluded.title, current_hp = case when public.bosses.defeated_at is null then greatest(1, least(excluded.max_hp, public.bosses.current_hp + excluded.max_hp - public.bosses.max_hp)) else public.bosses.current_hp end, max_hp = excluded.max_hp, damage_per_hit = excluded.damage_per_hit, final_question_id = excluded.final_question_id, unlocks_module_id = excluded.unlocks_module_id;
